                         <div className="bg-white/80 p-4 rounded-3xl shadow-xl flex flex-col items-center space-y-2 scale-in">
                            <span className="text-3xl">🔒</span>
                            <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest">Tahap Terkunci</span>
                         </div>
