                      <span className="text-2xl transform transition-transform group-hover:scale-125">
                        {isDone ? (user.isAdmin ? '⭐' : '✅') : '🔒'}
                      </span>
                      <span className={`text-[9px] font-black text-center ${isDone ? (user.isAdmin ? 'text-amber-700' : 'text-emerald-700') : 'text-gray-400'}`}>
                        {level.title}
