      if (currentIndex <= 9) return "Asas Syaddah (Sabdu): Tekankan suara pada huruf yang bersabdu seolah-olah ada dua huruf.";
      if (currentIndex <= 14) return "Syaddah dalam Surah Al-Fatihah: Beri tumpuan pada sebutan basmalah dan kalimah 'Ad-Dhallin'.";
      if (currentIndex >= 30 && currentIndex <= 34) return "Latihan Potongan Surah: Perhatikan makhraj and dengung pada ayat-ayat Al-Quran.";
      return "Latihan Syaddah: Gabungan hukum syaddah, mad, und sukun dalam ayat Al-Quran.";
    }
    if (level.id === 7) {
      if (currentIndex <= 5) return "Izhar Halqi: Bunyi Nun mati atau Tanwin dibaca dengan JELAS und terang apabila bertemu huruf halq (ء هـ ع ح غ خ).";
      if (currentIndex <= 7) return "Idgham Ma'al Ghunnah: Memasukkan bunyi Nun mati ke dalam huruf seterusnya dengan DENGUNG (ي ن م و).";
      if (currentIndex === 8) return "Idgham Bila Ghunnah: Memasukkan bunyi Nun mati ke dalam huruf seterusnya TANPA DENGUNG (ل ر).";
      if (currentIndex === 9) return "Iqlab: Menukarkan bunyi Nun mati kepada bunyi MIM (م) dengan dengung apabila bertemu huruf BA (ب).";
      if (currentIndex <= 11) return "Ikhfa' Haqiqi: Menyembunyikan bunyi Nun mati antara bunyi Izhar und Idgham dengan dengung (15 huruf).";
      if (currentIndex <= 21) return "Latihan Campuran: Kenalpasti hukum tajwid bagi setiap perkataan di bawah.";
      if (currentIndex === 22) return "Ikhfa' Syafawi: Bunyi Mim mati (م) dibaca secara SAMAR und DENGUNG apabila bertemu huruf BA (ب).";
      if (currentIndex === 23) return "Idgham Mimi: Memasukkan bunyi Mim mati ke dalam huruf MIM (م) seterusnya dengan DENGUNG.";
      if (currentIndex >= 24 && currentIndex <= 25) return "Izhar Syafawi: Bunyi Mim mati dibaca dengan JELAS (Tanpa Dengung) apabila bertemu SEMUA huruf selain ب und م.";
      if (currentIndex >= 26) return "Latihan Sukar: Gabungan pelbagai hukum tajwid dalam ayat Al-Quran yang lebih panjang.";
      return null;
    }
    return null;
  }, [level.id, currentIndex]);

  const pageTitle = useMemo(() => {
    if (level.id === 7) {
      const izharLetters = ['Hamzah (ء)', 'Ha (هـ)', 'Ain (ع)', 'Ha (ح)', 'Ghain (غ)', 'Kha (خ)'];
      if (currentIndex <= 5) return `Izhar Halqi: ${izharLetters[currentIndex]}`;
      if (currentIndex === 6) return "Idgham Ma'al Ghunnah (ي & ن)";
      if (currentIndex === 7) return "Idgham Ma'al Ghunnah (م & و)";
      if (currentIndex === 8) return "Idgham Bila Ghunnah (ل & ر)";
      if (currentIndex === 9) return "Iqlab (ب)";
      if (currentIndex === 10) return "Ikhfa' Haqiqi: ت ث ج د ذ ز س sh";
      if (currentIndex === 11) return "Ikhfa' Haqiqi: ص ض ط ظ ف ق ك";
      if (currentIndex <= 21) return `Latihan Campuran (Halaman ${currentIndex - 11})`;
      if (currentIndex === 22) return "Ikhfa' Syafawi (Mim + Ba)";
      if (currentIndex === 23) return "Idgham Mimi (Mim + Mim)";
      if (currentIndex === 24) return "Izhar Syafawi (Halaman 1)";
      if (currentIndex === 25) return "Izhar Syafawi (Halaman 2)";
      if (currentIndex >= 26) return `Latihan Sukar (Halaman ${currentIndex - 25})`;
      return `Latihan IQRA 7 (Halaman ${currentIndex + 1})`;
    }
    if (level.id === 6) {
      if (currentIndex <= 9) return `Syaddah Asas (Halaman ${currentIndex + 1})`;
      if (currentIndex <= 14) return `Al-Fatihah (Halaman ${currentIndex + 1})`;
      if (currentIndex >= 20 && currentIndex <= 24) return `Latihan Ayat (Halaman ${currentIndex + 1})`;
      if (currentIndex >= 30 && currentIndex <= 34) return `Latihan Quran (Halaman ${currentIndex + 1})`;
      return `Latihan IQRA 6 (Halaman ${currentIndex + 1})`;
    }
    if (level.id === 5) {
      if (currentIndex <= 5) return 'Mad Asli';
      if (currentIndex <= 33) return 'Sukun (Mati)';
      return `Latihan IQRA 5 (Halaman ${currentIndex + 1})`;
    }
    return level.title;
  }, [level.id, currentIndex]);

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-1`}>
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
           </svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-500`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className={`text-[10px] font-black text-${colorTheme}-600 uppercase tracking-widest`}>
            {mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}
          </span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-6">
          <div className="text-center space-y-2">
             <h2 className="text-3xl font-black text-gray-800 tracking-tight">
               {pageTitle}
             </h2>
             {guidance && (
               <div className={`max-w-lg mx-auto bg-${colorTheme}-50 border-${colorTheme}-100 p-4 rounded-2xl flex items-start space-x-3 text-left shadow-sm animate-in zoom-in-95 duration-500`}>
                  <div className={`mt-1 flex-shrink-0 w-6 h-6 bg-${colorTheme}-600 rounded-full flex items-center justify-center text-white text-[10px] font-black shadow-lg`}>i</div>
                  <div className={`text-xs sm:text-sm text-${colorTheme}-900 font-medium leading-relaxed`}>
                    <span className="font-bold block mb-0.5">Hukum Tajwid:</span>
                    {guidance}
                  </div>
               </div>
             )}
          </div>

          <div 
            className={`w-full grid ${isIqra1 ? 'grid-cols-1 max-w-lg' : (isVerticalList ? 'grid-cols-1 gap-4 max-w-3xl' : (isHorizontalList ? 'grid-cols-3 gap-4 max-w-4xl' : (isEightGrid ? 'grid-cols-2 gap-4 max-w-3xl' : 'grid-cols-3 gap-3 sm:gap-6 max-w-4xl')))}`} 
            dir="rtl"
          >
            {currentItems.map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word as string, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full ${isIqra1 ? 'py-20 px-10 rounded-[5rem] border-4 border-emerald-300 shadow-2xl bg-white hover:border-emerald-500' : (isVerticalList ? 'py-8 px-8 rounded-3xl' : (isHorizontalList ? 'aspect-[4/3] rounded-3xl' : 'aspect-square rounded-3xl sm:rounded-[2.5rem]'))} bg-white shadow-md border-2 border-${colorTheme}-100 text-${colorTheme}-900 flex items-center justify-center arabic-text select-none transition-all duration-300 relative ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400 ring-4 ring-emerald-50' : (isIqra1 ? 'hover:scale-[1.05] active:scale-95 hover:shadow-2xl' : 'hover:scale-[1.03] active:scale-95 hover:shadow-2xl hover:border-emerald-300')}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-4 right-4">
                    <div className={`w-5 h-5 border-2 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div>
                  </div>
                )}
                <span className={`leading-tight translate-y-2 font-black text-center transition-transform duration-300 ${isAnimating === vIdx ? 'scale-110' : ''} ${isIqra1 ? 'text-[14rem] sm:text-[18rem] text-emerald-950 drop-shadow-lg' : (isVerticalList ? 'text-2xl sm:text-3xl lg:text-4xl' : 'text-3xl sm:text-4xl md:text-5xl')}`}>
                  {word}
                </span>
                {isIqra1 && (
                  <div className="absolute bottom-6 left-1/2 -translate-x-1/2 opacity-20 group-hover:opacity-40 transition-opacity">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em]">Tap to hear</span>
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-4 w-full max-w-2xl bg-emerald-50 p-4 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-300 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                 {isLoadingAudio && isAnimating === idx && (
                  <div className="absolute top-1 right-1">
                    <div className="w-2 h-2 border border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                  </div>
                )}
                <span className={`arabic-text font-black text-3xl leading-[1.2] text-emerald-900 translate-y-1 transition-transform duration-300 ${isAnimating === idx ? 'scale-125' : ''}`}>
                  {letter}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-500 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-lg flex items-center space-x-2 bg-${colorTheme}-100 text-${colorTheme}-800 border-${colorTheme}-200`}>
          <span className={`w-2 h-2 rounded-full animate-pulse bg-${colorTheme}-500`}></span>
          <span>
            {mode === 'SEQUENTIAL' ? `Halaman ${currentIndex + 1} / ${data.length}` : `Review Halaman ${reviewPage + 1}`}
          </span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-8 mb-4">
        <button
          onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage}
          disabled={mode === 'SEQUENTIAL' && currentIndex === 0}
          className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all duration-300"
        >
          Kembali
        </button>
        <button
          onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage}
          className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-xl transition-all duration-300 bg-${colorTheme}-600 shadow-${colorTheme}-200 hover:bg-${colorTheme}-700 hover:scale-[1.02] active:scale-95`}
        >
          {mode === 'SEQUENTIAL' 
            ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya')
            : (reviewPage === 5 ? 'Selesai & Penerangan' : 'Seterusnya')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

export default PracticeSession;

import React, { useState, useEffect, useRef } from 'react';
import { IqraLevel } from '../types';
import { getQuizQuestions } from '../services/geminiService';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface QuizProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish?: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const Quiz: React.FC<QuizProps> = ({ level, onBack, onFinish }) => {
  const [questions, setQuestions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentStep, setCurrentStep] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [showResult, setShowResult] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    async function loadQuiz() {
      setLoading(true);
      const questionCount = level.id === 4 ? 10 : 5;
      const data = await getQuizQuestions(level.title, level.subtitle, questionCount);
      if (data && data.questions) {
        setQuestions(data.questions);
      }
      setLoading(false);
    }
    loadQuiz();
  }, [level]);

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current || !isAnswered) return;

    const distance = touchStartX.current - touchEndX.current;
    if (distance < -minSwipeDistance) {
      handleNext();
    }
  };

  const playFeedback = async (isCorrect: boolean) => {
    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const text = isCorrect ? "Alhamdulillah, Bagus! Jawapan anda tepat." : "Cuba lagi ya, anda pasti boleh!";

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Kore' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (e) {
      console.error("Feedback Audio Error:", e);
    }
  };

  const handleOptionClick = (index: number) => {
    if (isAnswered) return;
    setSelectedOption(index);
    setIsAnswered(true);

    const isCorrect = index === questions[currentStep].correctIndex;
    if (isCorrect) {
      setScore(s => s + 1);
    }

    playFeedback(isCorrect);
  };

  const handleNext = () => {
    if (currentStep < questions.length - 1) {
      setCurrentStep(s => s + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setShowResult(true);
    }
  };

  if (loading) {
    return (
      <div className="max-w-2xl mx-auto p-12 flex flex-col items-center justify-center space-y-6 fade-in min-h-screen">
        <div className="w-16 h-16 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
        <div className="text-center space-y-2">
          <p className="text-xl font-bold text-emerald-800 animate-pulse">Menjana soalan kuiz khas untuk anda...</p>
          <p className="text-sm text-gray-400 italic">Mencipta soalan (Senang ke Sukar) untuk {level.title}</p>
        </div>
        <Copyright />
      </div>
    );
  }

  if (showResult) {
    return (
      <div className="max-w-2xl mx-auto p-8 text-center space-y-8 animate-in zoom-in-95 duration-500 flex flex-col items-center min-h-screen">
        <div className="w-32 h-32 bg-emerald-100 rounded-full flex items-center justify-center mx-auto text-6xl shadow-inner animate-bounce">
          {score >= questions.length * 0.8 ? '🏆' : (score >= questions.length * 0.5 ? '⭐' : '💪')}
        </div>
        <div className="space-y-2">
          <h2 className="text-4xl font-black text-gray-900">
            {score === questions.length ? 'Mumtaz!' : (score >= questions.length * 0.7 ? 'Jayyid Jiddan!' : 'Teruskan Usaha!')}
          </h2>
          <p className="text-xl text-gray-500">Anda telah menyelesaikan kuiz {level.title}.</p>
          {onFinish && score >= questions.length * 0.6 && (
            <p className="text-emerald-600 font-bold bg-emerald-50 py-3 px-6 rounded-2xl mt-4 border border-emerald-100 inline-block animate-pulse">
              🎉 Tahap Seterusnya Telah Dibuka!
            </p>
          )}
        </div>
        <div className="bg-white p-10 rounded-[3rem] shadow-2xl border-4 border-emerald-50 inline-block px-20 relative">
          <div className="absolute -top-4 -left-4 w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg animate-float">🎯</div>
          <p className="text-sm text-gray-400 font-black uppercase tracking-[0.2em] mb-2">Skor Akhir</p>
          <p className="text-7xl font-black text-emerald-600">{score} / {questions.length}</p>
        </div>
        <div className="pt-8 flex flex-col items-center space-y-4 flex-1">
          <button 
            onClick={onFinish || onBack}
            className="px-16 py-5 bg-emerald-600 text-white rounded-3xl font-bold shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all hover:scale-105 active:scale-95 text-lg"
          >
            Selesai & Kembali
          </button>
          <button onClick={onBack} className="text-gray-400 font-bold hover:text-rose-500 transition-colors">Tutup Kuiz</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentQuestion = questions[currentStep];

  return (
    <div 
      className="max-w-2xl mx-auto p-4 md:p-8 animate-in fade-in slide-in-from-bottom-4 min-h-screen flex flex-col"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="flex items-center justify-between mb-8">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors flex items-center space-x-1 group">
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
          <span className="font-bold">Batal</span>
        </button>
        <div className="flex flex-col items-end">
          <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Progress Kuiz</span>
          <div className="flex items-center space-x-2">
            <span className="text-xs font-bold text-gray-400">
              {currentStep + 1} / {questions.length}
            </span>
            <div className="w-24 h-2 bg-gray-100 rounded-full overflow-hidden shadow-inner">
              <div 
                className="h-full bg-emerald-500 transition-all duration-700 ease-out" 
                style={{ width: `${((currentStep + 1) / questions.length) * 100}%` }}
              ></div>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-8 flex-1">
        <div className="bg-white p-8 sm:p-12 rounded-[2.5rem] shadow-xl border-2 border-emerald-50 relative overflow-hidden group hover:shadow-2xl transition-all duration-500">
          <div className="absolute top-0 left-0 w-3 h-full bg-emerald-500 group-hover:w-4 transition-all duration-300"></div>
          <div className="flex justify-center mb-4">
             <span className="px-4 py-1 bg-emerald-50 text-emerald-600 text-[10px] font-black uppercase tracking-widest rounded-full border border-emerald-100 shadow-sm">
               {currentStep < 3 ? 'TAHAP: SENANG' : (currentStep < 7 ? 'TAHAP: SEDERHANA' : 'TAHAP: SUKAR')}
             </span>
          </div>
          <h3 className="text-2xl sm:text-3xl font-black text-gray-900 text-center leading-relaxed arabic-text transition-transform duration-300 group-hover:scale-[1.02]">
            {currentQuestion.question}
          </h3>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {currentQuestion.options.map((option: string, index: number) => {
            let bgColor = "bg-white";
            let borderColor = "border-gray-100";
            let textColor = "text-gray-700";
            let animationClass = "";
            let icon = null;

            if (isAnswered) {
              if (index === currentQuestion.correctIndex) {
                bgColor = "bg-emerald-500";
                borderColor = "border-emerald-600 shadow-xl shadow-emerald-100";
                textColor = "text-white";
                animationClass = "animate-subtle-pulse";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                  </svg>
                );
              } else if (selectedOption === index) {
                bgColor = "bg-rose-500";
                borderColor = "border-rose-600 shadow-xl shadow-rose-100";
                textColor = "text-white";
                animationClass = "animate-shake";
                icon = (
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                );
              } else {
                bgColor = "bg-gray-50";
                borderColor = "border-gray-100";
                textColor = "text-gray-300 opacity-50";
              }
            }

            return (
              <button
                key={index}
                onClick={() => handleOptionClick(index)}
                disabled={isAnswered}
                className={`relative p-6 rounded-3xl border-4 text-xl font-bold transition-all duration-300 text-center flex flex-col items-center justify-center min-h-[140px] shadow-sm ${bgColor} ${borderColor} ${textColor} ${animationClass} ${!isAnswered ? 'hover:border-emerald-300 hover:shadow-2xl hover:-translate-y-2 active:scale-95' : ''}`}
              >
                <span className={`arabic-text text-4xl mb-1 transition-transform duration-300 ${isAnswered && index === currentQuestion.correctIndex ? 'scale-110' : ''}`}>{option}</span>
                {isAnswered && index === currentQuestion.correctIndex && (
                  <span className="text-[10px] font-black uppercase tracking-widest opacity-80">Jawapan Betul</span>
                )}
                {icon && (
                  <div className="absolute top-3 right-3 animate-in zoom-in-0 duration-300">
                    {icon}
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {isAnswered && (
          <div className="bg-emerald-50 p-8 rounded-[2rem] border-2 border-emerald-100 animate-in slide-in-from-top-4 shadow-xl shadow-emerald-100/50">
            <div className="flex items-start space-x-4">
              <div className={`mt-1 flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center text-xl shadow-md transition-transform duration-500 animate-bounce ${selectedOption === currentQuestion.correctIndex ? 'bg-emerald-600 text-white' : 'bg-rose-500 text-white'}`}>
                {selectedOption === currentQuestion.correctIndex ? '✅' : '💡'}
              </div>
              <div className="flex-1">
                <p className="font-black text-emerald-900 text-xl mb-1">
                  {selectedOption === currentQuestion.correctIndex ? 'Mumtaz! (Hebat)' : 'Belajar Sesuatu!'}
                </p>
                <p className="text-emerald-800 leading-relaxed font-medium">
                  {currentQuestion.explanation}
                </p>
              </div>
            </div>
            <div className="mt-8 space-y-3">
              <button
                onClick={handleNext}
                className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-black text-lg hover:bg-emerald-700 transition-all shadow-lg hover:shadow-emerald-200 active:scale-[0.98] flex items-center justify-center space-x-2 group"
              >
                <span>{currentStep === questions.length - 1 ? 'Lihat Keputusan Akhir' : 'Soalan Seterusnya'}</span>
                <svg className="w-5 h-5 group-hover:translate-x-2 transition-transform duration-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 5l7 7-7 7" />
                </svg>
              </button>
              <p className="text-center text-emerald-400 text-[10px] font-bold uppercase tracking-widest">
                Tips: Swipe <b>Kanan</b> untuk Seterusnya
              </p>
            </div>
          </div>
        )}
      </div>
      <Copyright />
    </div>
  );
};

export default Quiz;

import React, { useRef, useState } from 'react';
import { User, IqraLevel } from '../types';
import { GoogleGenAI } from "@google/genai";
import Copyright from './Copyright';

interface ProfileViewProps {
  user: User;
  unlockedLevels: number[];
  levels: IqraLevel[];
  onBack: () => void;
  onUpdateUser?: (updatedUser: User) => void;
}

const ProfileView: React.FC<ProfileViewProps> = ({ user, unlockedLevels, levels, onBack, onUpdateUser }) => {
  const progressPercent = Math.round((unlockedLevels.length / levels.length) * 100);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [feedback, setFeedback] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [feedbackResponse, setFeedbackResponse] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onUpdateUser) {
      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdateUser({ ...user, photoURL: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendFeedback = async () => {
    if (!feedback.trim()) return;
    setIsSending(true);

    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Seorang pengguna aplikasi Advancekids IQRA PINTAR telah menghantar maklum balas berikut: "${feedback}". Sebagai pembangun (developer) yang ramah dan berunsurkan nilai Islam, berikan ucapan terima kasih yang sangat hangat, mendoakan mereka, dan memberitahu bahawa cadangan mereka sangat dihargai. Jawab dalam Bahasa Melayu yang sopan.`,
      });

      setFeedbackResponse(response.text || "Terima kasih atas maklum balas anda! Kami amat menghargainya.");
      setFeedback('');
    } catch (error) {
      console.error("Feedback error:", error);
      setFeedbackResponse("Terima kasih! Maklum balas anda telah diterima oleh pasukan kami.");
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-4 md:p-8 space-y-8 animate-in fade-in zoom-in-95 duration-300 min-h-screen flex flex-col">
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <button 
            onClick={onBack}
            className="p-3 bg-white shadow-sm rounded-2xl hover:bg-gray-50 text-emerald-600 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <h2 className="text-3xl font-black text-gray-900">Profil Pelajar</h2>
        </div>

        <div className="hidden sm:flex items-center space-x-2 bg-emerald-50 px-4 py-2 rounded-2xl border border-emerald-100">
          <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
          <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Akaun Aktif</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8 flex-1">
        <div className="md:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-emerald-50 flex flex-col items-center text-center relative overflow-hidden">
            <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-50 rounded-full -mr-12 -mt-12 opacity-50"></div>

            <div className="relative mb-6 group z-10">
              <img src={user.photoURL} alt="profile" className={`w-32 h-32 rounded-3xl border-4 ${user.isAdmin ? 'border-amber-400' : 'border-emerald-100'} shadow-lg object-cover transition-transform duration-500 group-hover:scale-105`} />
              <div className={`absolute -bottom-2 -right-2 ${user.isAdmin ? 'bg-amber-600' : 'bg-emerald-600'} text-white text-[10px] font-black px-3 py-1 rounded-full shadow-md z-20`}>
                {user.isAdmin ? 'PENTADBIR' : 'PELAJAR'}
              </div>

              <button 
                onClick={() => fileInputRef.current?.click()}
                className="absolute inset-0 bg-black/40 rounded-3xl flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-30"
              >
                <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
              </button>
              <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept="image/*" className="hidden" />
            </div>

            <h3 className="text-2xl font-black text-gray-900 leading-tight z-10">{user.name}</h3>
            <p className={`${user.isAdmin ? 'text-amber-600 bg-amber-50' : 'text-emerald-600 bg-emerald-50'} font-bold text-sm px-4 py-1 rounded-full mt-2 z-10`}>
              {user.isAdmin ? 'Akses Penuh' : `${user.age} Tahun`}
            </p>

            <button 
              onClick={() => fileInputRef.current?.click()}
              className="mt-4 text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline z-10"
            >
              Tukar Foto Profil
            </button>

            <div className="w-full mt-8 pt-8 border-t border-gray-50 space-y-4 text-left z-10">
              <div className="flex flex-col items-start space-y-1">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Email Peribadi</span>
                <span className="text-sm font-bold text-gray-700 break-all">{user.email}</span>
              </div>
              <div className="flex flex-col items-start space-y-1">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Email Waris</span>
                <span className="text-sm font-bold text-gray-700 break-all">{user.parentEmail}</span>
              </div>
            </div>
          </div>

          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] shadow-xl text-white space-y-4 relative overflow-hidden">
            <div className="absolute top-0 right-0 -mr-4 -mt-4 opacity-10">
              <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"/></svg>
            </div>

            <h4 className="text-xl font-black flex items-center space-x-2">
              <span>Maklum Balas</span>
              <span className="text-sm bg-white/20 px-2 py-0.5 rounded-lg font-bold">DEV</span>
            </h4>

            {feedbackResponse ? (
              <div className="space-y-4 animate-in fade-in zoom-in-95 duration-500">
                <p className="text-sm leading-relaxed font-medium bg-white/10 p-4 rounded-2xl italic">
                  "{feedbackResponse}"
                </p>
                <button 
                  onClick={() => setFeedbackResponse(null)}
                  className="w-full py-3 bg-white text-indigo-700 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-indigo-50 transition-colors"
                >
                  Hantar Lagi
                </button>
              </div>
            ) : (
              <div className="space-y-3">
                <p className="text-xs text-blue-100 font-medium leading-relaxed">Ada cadangan atau masalah? Beritahu pembangun kami!</p>
                <textarea 
                  value={feedback}
                  onChange={(e) => setFeedback(e.target.value)}
                  placeholder="Tulis maklum balas anda..."
                  className="w-full bg-white/10 border border-white/20 rounded-2xl p-4 text-sm focus:outline-none focus:ring-2 focus:ring-white/50 placeholder-blue-200 min-h-[100px] resize-none"
                />
                <button 
                  onClick={handleSendFeedback}
                  disabled={isSending || !feedback.trim()}
                  className="w-full py-4 bg-white text-indigo-700 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-indigo-50 transition-all active:scale-95 disabled:opacity-50 flex items-center justify-center space-x-2"
                >
                  {isSending ? (
                    <div className="w-5 h-5 border-2 border-indigo-700 border-t-transparent rounded-full animate-spin"></div>
                  ) : (
                    <>
                      <span>Hantar Maklum Balas</span>
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7-7 7M5 5l7 7-7 7"/></svg>
                    </>
                  )}
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="md:col-span-2 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-emerald-50 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-48 h-48 bg-emerald-50/50 rounded-full -mr-24 -mt-24"></div>

            <div className="flex items-center justify-between mb-8 relative z-10">
              <h4 className="text-xl font-black text-gray-900">Kemajuan Pembelajaran</h4>
              <div className="flex flex-col items-end">
                <span className={`text-3xl font-black ${user.isAdmin ? 'text-amber-600' : 'text-emerald-600'}`}>{progressPercent}%</span>
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Keseluruhan</span>
              </div>
            </div>

            <div className="space-y-8 relative z-10">
              <div className="w-full h-4 bg-emerald-50 rounded-full overflow-hidden p-1 shadow-inner">
                <div 
                  className={`h-full ${user.isAdmin ? 'bg-amber-500' : 'bg-emerald-500'} rounded-full shadow-lg transition-all duration-1000 ease-out`}
                  style={{ width: `${progressPercent}%` }}
                ></div>
              </div>

              <div className="grid grid-cols-3 sm:grid-cols-5 gap-4">
                {levels.map(level => {
                  const isDone = unlockedLevels.includes(level.id);
                  return (
                    <div 
                      key={level.id} 
                      className={`p-4 rounded-3xl border-2 flex flex-col items-center space-y-2 transition-all duration-300 ${
                        isDone 
