              <div className="pt-6 border-t border-gray-50">
                <div className={`flex items-center space-x-4 ${user.isAdmin ? 'bg-gray-800' : 'bg-emerald-600'} p-6 rounded-[2rem] text-white shadow-xl shadow-emerald-100 transition-all hover:scale-[1.02]`}>
