               className={`w-full bg-white p-10 rounded-[2.5rem] border border-transparent shadow-sm hover:shadow-xl hover:border-amber-100 transition-all duration-300 flex flex-col items-center text-center group relative ${isAnimating === vIdx ? 'scale-[0.98] border-amber-300' : ''}`}
