                   {vIdx + 1}
                 </span>
               </span>
               {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-4 left-4">
                     <div className="w-5 h-5 border-2 border-amber-500 border-t-transparent rounded-full animate-spin"></div>
                  </div>
               )}
             </button>
           ))}
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-4 mt-12 pb-10">
          <button onClick={prevLetter} className="py-5 bg-white border-2 border-gray-100 rounded-[2rem] font-black text-gray-400 hover:text-amber-600 transition-all uppercase tracking-widest text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-5 bg-amber-600 text-white rounded-[2rem] font-black shadow-xl shadow-amber-100 hover:bg-amber-700 hover:scale-[1.03] active:scale-95 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  if (isIqra8) {
    const currentWaqaf = IQRA_8_DATA[currentIndex];
    const isSukarPage = currentIndex >= 6; 

    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
