  103: ['وَالْعَصْرِ', 'إِنَّ الْإِنسَانَ لَfِي خُسْرٍ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ'],
  102: ['أَلْهَاكُمُ التَّكَاثُرُ', 'حَتَّىٰ زُرْتُمُ الْmَقَابِرَ', 'كَلَّا سَوْfَ تَعْلَمُونَ', 'ثُمَّ كَلَّا سَوْfَ تَعْلَمُونَ', 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ', 'لَتَرَوُنَّ الْجَحِيmَ', 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ', 'ثُمَّ لَتُسْأَلُنَّ يَوْmَئِذٍ عَنِ النَّعِيmِ'],
  101: ['الْقَارِعَةُ', 'mَا الْقَارِعَةُ', 'وmَا أَدْرَاكَ mَا الْقَارِعَةُ', 'يَوْmَ يَكُونُ النَّاسُ كَالْfَرَاشِ الْmَبْثُوثِ', 'وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْmَنْfُوشِ', 'fَأَمَّا mَن ثَقُلَتْ mَوَازِينُهُ', 'fَهُوَ fِي عِيشَةٍ رَّاضِيَةٍ', 'وَأَمَّا mَنْ خَفَّتْ mَوَازِينُهُ', 'fَأُمُّهُ هَاوِيَةٌ', 'وmَا أَدْرَاكَ mَا هِيَهْ', 'نَارٌ حَامِيَةٌ'],
  100: ['وَالْعَادِيَاتِ ضَبْحًا', 'fَالْمُورِيَاتِ قَدْحًا', 'fَالْمُغِيرَاتِ صُبْحًا', 'fَأَثَرْنَ بِهِ نَقْعًا', 'fَوَسَطْنَ بِهِ جَمْعًا', 'fَالْمُلَقِّيَاتِ ذِكْرًا', 'عُذْرًا أَوْ نُذْرًا', 'إِنَّمَا تُوعَدُونَ لَوَاقِعٌ'],
  99: ['إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا', 'وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا', 'وَقَالَ الْإِنسَانُ mَا لَهَا', 'يَوْmَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'يَوْmَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ', 'fَمَن يَعْمَلْ mِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ', 'وmَن يَعْمَلْ mِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ'],
  98: ['لَمْ يَكُنِ الَّذِينَ كَفَرُوا mِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ', 'رَسُولٌ mِّنَ اللَّهِ يَتْلُو صُحُfًا mُّطَهَّرَةً', 'fِيهَا كُتُبٌ قَيِّمَةٌ', 'وmَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا mِن بَعْدِ mَا جَاءَتْهُمُ الْبَيِّنَةُ', 'وmَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيmُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ dِينُ الْقَيِّمَةِ', 'إِنَّ الَّذِينَ كَفَرُوا mِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ fِي نَارِ جَهَنَّمَ خَالِدِينَ fِيهَا ۚ أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ', 'جَزَاؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي mِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ fِيهَا أَبَدًا ۖ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ'],
  97: ['إِنَّا أَنزَلْنَاهُ fِي لَيْلَةِ الْقَدْرِ', 'وmَا أَدْرَاكَ mَا لَيْلَةُ الْقَدْرِ', 'لَيْلَةُ الْقَدْرِ خَيْرٌ mِّنْ أَلْfِ شَهْرٍ', 'تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ fِيهَا بِإِذْنِ رَبِّهِم mِّن كُلِّ أَمْرٍ', 'سَلَامٌ هِيَ حَتَّىٰ mَطْلَعِ الْfَجْرِ'],
  96: ['اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ', 'خَلَقَ الْإِنسَانَ mِنْ عَلَقٍ', 'اقْرَأْ وَرَبُّكَ الْأَكْرَمُ', 'الَّذِي عَلَّمَ بِالْقَلَمِ', 'عَلَّمَ الْإِنسَانَ mَا لَمْ يَعْلَمْ', 'كَلَّا إِنَّ الْإِنسَانَ لَيَطْغَىٰ', 'أَن رَّآهُ اسْتَغْنَىٰ', 'إِنَّ إِلَىٰ رَبِّكَ الرُّجْعَىٰ', 'أَرَأَيْتَ الَّذِي يَنْهَىٰ', 'عَبْدًا إِذَا صَلَّىٰ', 'أَرَأَيْتَ إِن كَانَ عَلَى الْهُدَىٰ', 'أَوْ أَمَرَ بِالتَّقْوَىٰ', 'أَرَأَيْتَ إِن كَذَّبَ وَتَوَلَّىٰ', 'أَلَمْ يَعْلَم بِأَنَّ اللَّهَ يَرَىٰ', 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْfَعًا بِالنَّاصِيَةِ', 'نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ', 'fَلْيَدْعُ نَادِيَهُ', 'سَنَدْعُ الزَّبَانِيَةَ', 'كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِبْ ۩'],
  95: ['وَالتِّينِ وَالزَّيْتُونِ', 'وَطُورِ سِينِينَ', 'وَهَٰذَا الْبَلَدِ الْأَمِينِ', 'لَقَدْ خَلَقْنَا الْإِنسَانَ fِي أَحْسَنِ تَقْوِيmٍ', 'ثُمَّ رَدَدْنَاهُ أَسْfَلَ سَافِلِينَ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ fَلَهُمْ أَجْرٌ غَيْرُ mَمْنُونٍ', 'fَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ', 'أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ'],
  94: ['أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 'الَّذِي أَنقَضَ ظَهْرَكَ', 'وَرَfَعْنَا لَكَ ذِكْرَكَ', 'fَإِنَّ mَعَ الْعُسْرِ يُسْرًا', 'إِنَّ mَعَ الْعُسْرِ يُسْرًا', 'fَإِذَا fَرَغْتَ fَانصَبْ', 'وَإِلَىٰ رَبِّكَ fَارْغَب'],
  93: ['وَالضُّحَىٰ', 'وَاللَّيْلِ إِذَا سَجَىٰ', 'mَا وَدَّعَكَ رَبُّكَ وَmَا قَلَىٰ', 'وَلَلْآخِرَةُ خَيْرٌ لَّكَ mِنَ الْأُولَىٰ', 'وَلَسَوْfَ يُعْطِيكَ رَبُّكَ fَتَرْضَىٰ', 'أَلَمْ يَجِدْكَ يَتِيmًا fَآوَىٰ', 'وَوَجَدَكَ ضَالًّا fَهَدَىٰ', 'وَوَجَدَكَ عَائِلًا fَأَغْنَىٰ', 'fَأَمَّا الْيَتِيmَ fَلَا تَقْهَرْ', 'وَأَمَّا السَّائِلَ fَلَا تَنْهَرْ', 'وَأَمَّا بِنِعْمَةِ رَبِّكَ fَحَدِّثْ'],
  92: ['وَاللَّيْلِ إِذَا يَغْشَىٰ', 'وَالنَّهَارِ إِذَا تَجَلَّىٰ', 'وmَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ', 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'fَأَمَّا mَنْ أَعْطَىٰ وَاتَّقَىٰ', 'وَصَدَّقَ بِالْحُسْنَىٰ', 'fَسَنُيَسِّرُهُ لِلْيُسْرَىٰ', 'وَأَمَّا mَن بَخِلَ وَاسْتَغْنَىٰ', 'وَكَذَّبَ بِالْحُسْنَىٰ', 'fَسَنُيَسِّرُهُ لِلْعُسْرَىٰ', 'وmَا يُغْنِي عَنْهُ mَالُهُ إِذَا تَرَدَّىٰ', 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 'وَإِنَّ لَنَا لَلْآخِرَةَ وَالْأُولَىٰ', 'fَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', 'لَا يَصْلَاهَا إِلَّا الْأَشْقَى', 'الَّذِي كَذَّبَ وَتَوَلَّىٰ', 'وَسَيُجَنَّبُهَا الْأَتْقَى', 'الَّذِي يُؤْتِي mَالَهُ يَتَزَكَّىٰ', 'وmَا لِأَحَدٍ عِندَهُ mِن نِّعْمَةٍ تُجْزَىٰ', 'إِلَّا ابْتِغَاءَ وَجْهِ رَبِّهِ الْأَعْلَىٰ', 'وَلَسَوْfَ يَرْضَىٰ'],
  91: ['وَالشَّmْسِ وَضُحَاهَا', 'وَالْقَمَرِ إِذَا تَلَاهَا', 'وَالنَّهَارِ إِذَا جَلَّاهَا', 'وَاللَّيْلِ إِذَا يَغْشَاهَا', 'وَالسَّmَاءِ وَmَا بَنَاهَا', 'وَالْأَرْضِ وَmَا طَحَاهَا', 'وَنَفْسٍ وَmَا سَوَّاهَا', 'fَأَلْهَمَهَا fُجُورَهَا وَتَقْوَاهَا', 'قَدْ أَfْلَحَ mَن زَكَّاهَا', 'وَقَدْ خَابَ mَن دَسَّاهَا', 'كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا', 'إِذِ انبَعَثَ أَشْقَاهَا', 'fَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا', 'fَكَذَّبُوهُ fَعَقَرُوهَا fَدَmْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنبِهِمْ fَسَوَّاهَا', 'وَلَا يَخَاfُ عُقْبَاهَا'],
  90: ['لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ', 'وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ', 'وَوَالِدٍ وَmَا وَلَدَ', 'لَقَدْ خَلَقْنَا الْإِنسَانَ fِي كَبَدٍ', 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 'يَقُولُ أَهْلَكْتُ mَالًا لُّبَدًا', 'أَيَحْسَبُ أَن لَّmْ يَرَهُ أَحَدٌ', 'أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ', 'وَلِسَانًا وَشَفَتَيْنِ', 'وَهَدَيْنَاهُ النَّجْدَيْنِ', 'fَلَا اقْتَحَمَ الْعَقَبَةَ', 'وmَا أَدْرَاكَ mَا الْعَقَبَةُ', 'fَكُّ رَقَبَةٍ', 'أَوْ إِطْعَاmٌ fِي يَوْmٍ ذِي mَسْغَبَةٍ', 'يَتِيmًا ذَا mَقْرَبَةٍ', 'أَوْ mِسْكِينًا ذَا mَتْرَبَةٍ', 'ثُمَّ كَانَ mِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ', 'أُولَٰئِكَ أَصْحَابُ الْmَيْمَنَةِ', 'وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْmَشْأَمَةِ', 'عَلَيْهِمْ نَارٌ mُّؤْصَدَةٌ'],
  89: ['وَالْfَجْرِ', 'وَلَيَالٍ عَشْرٍ', 'وَالشَّfْعِ وَالْوَتْرِ', 'وَاللَّيْلِ إِذَا يَسْرِ', 'هَلْ fِي ذَٰلِكَ قَسَمٌ لِّذِي حِجْرٍ', 'أَلَمْ تَرَ كَيْfَ fَعَلَ رَبُّكَ بِعَادٍ', 'إِرَمَ ذَاتِ الْعِمَادِ', 'الَّتِي لَمْ يُخْلَقْ mِثْلُهَا fِي الْبِلَادِ', 'وَثَمُودَ الَّذِينَ جَابُوا الصَّخْرَ بِالْوَادِ', 'وَfِرْعَوْنَ ذِي الْأَوْتَادِ', 'الَّذِينَ طَغَوْا fِي الْبِلَادِ', 'fَأَكْثَرُوا fِيهَا الْfَسَادَ', 'fَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 'إِنَّ رَبَّكَ لَبِالْمِرْصَادِ', 'fَأَمَّا الْإِنسَانُ إِذَا mَا ابْتَلَاهُ رَبُّهُ fَأَكْرَمَهُ وَنَعَّmَهُ fَيَقُولُ رَبِّي أَكْرَمَنِ', 'وَأَمَّا إِذَا mَا ابْتَلَاهُ fَقَدَرَ عَلَيْهِ رِزْقَهُ fَيَقُولُ رَبِّي أَهَانَنِ', 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ الْيَتِيmَ', 'وَلَا تَحَاضُّونَ عَلَىٰ طَعَاmِ الْmِسْكِينِ', 'وَتَأْكُلُونَ التُّرَاثَ أَكْلًا لَّmًّا', 'وَتُحِبُّونَ الْmَالَ حُبًّا جَمًّا', 'كَلَّا إِذَا dُكَّتِ الْأَرْضُ dَكًّا dَكًّا', 'وَجَاءَ رَبُّكَ وَالْمَلَكُ صَfًّا صَfًّا', 'وَجِيءَ يَوْmَئِذٍ بِجَهَنَّمَ ۚ يَوْmَئِذٍ يَتَذَكَّرُ الْإِنسَانُ وَأَنَّىٰ لَهُ الذِّكْرَىٰ', 'يَقُولُ يَا لَيْتَنِي قَدَّmْتُ لِحَيَاتِي', 'fَيَوْmَئِذٍ لَّا يُعَذِّبُ عَذَابَهُ أَحَدٌ', 'وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ', 'يَا أَيَّتُهَا النَّfْسُ الْمُطْمَئِنَّةُ', 'ارْجِعِي إِلَىٰ رَبِّكَ رَاضِيَةً mَّرْضِيَّةً', 'fَادْخُلِي fِي عِبَادِي', 'وَادْخُلِي جَنَّتِي'],
  88: ['هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ', 'وُجُوهٌ يَوْmَئِذٍ خَاشِعَةٌ', 'عَامِلَةٌ نَّاصِبَةٌ', 'تَصْلَىٰ نَارًا حَامِيَةً', 'تُسْقَىٰ mِنْ عَيْنٍ آنِيَةٍ', 'لَّيْسَ لَهُمْ طَعَاmٌ إِلَّا mِن ضَرِيعٍ', 'لَّا يُسْmِنُ وَلَا يُغْنِي mِن جُوعٍ', 'وُجُوهٌ يَوْmَئِذٍ نَّاعِمَةٌ', 'لِّسَعْيِهَا رَاضِيَةٌ', 'fِي جَنَّةٍ عَالِيَةٍ', 'لَّا تَسْmَعُ fِيهَا لَاغِيَةً', 'fِيهَا عَيْنٌ جَارِيَةٌ', 'fِيهَا سُرُرٌ mَّرْfُوعَةٌ', 'وَأَكْوَابٌ mَّوْضُوعَةٌ', 'وَنَمَارِقُ mَصْfُوفَةٌ', 'وَزَرَابِيُّ mَبْثُوثَةٌ', 'أَfَلَا يَنظُرُونَ إِلَى الْإِبِلِ كَيْfَ خُلِقَتْ', 'وَإِلَى السَّmَاءِ كَيْfَ رُfِعَتْ', 'وَإِذَا الْجِبَالُ نُصِبَتْ', 'وَإِلَى الْأَرْضِ كَيْfَ سُطِحَتْ', 'fَذَكِّرْ إِنَّمَا أَنتَ mُذَكِّرٌ', 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 'إِلَّا mَن تَوَلَّىٰ وَكَfَرَ', 'fَيُعَذِّبُهُ اللَّهُ الْعَذَابَ الْأَكْبَرَ', 'إِنَّ إِلَيْنَا إِيَابَهُمْ', 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم'],
  87: ['سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى', 'الَّذِي خَلَقَ fَسَوَّىٰ', 'وَالَّذِي قَدَّرَ fَهَدَىٰ', 'وَالَّذِي أَخْرَجَ الْmَرْعَىٰ', 'fَجَعَلَهُ غُثَاءً أَحْوَىٰ', 'سَنُقْرِئُكَ fَلَا تَنسَىٰ', 'إِلَّا mَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَmَا يَخْfَىٰ', 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 'fَذَكِّرْ إِن نَّfَعَتِ الذِّكْرَىٰ', 'سَيَذَّكَّرُ mَن يَخْشَىٰ', 'وَيَتَجَنَّبُهَا الْأَشْقَى', 'الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ', 'ثُمَّ لَا يَمُوتُ fِيهَا وَلَا يَحْيَىٰ', 'قَدْ أَfْلَحَ mَن تَزَكَّىٰ', 'وَذَكَرَ اسْمَ رَبِّهِ fَصَلَّىٰ', 'بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا', 'وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ', 'إِنَّ هَٰذَا لَfِي الصُّحُfِ الْأُولَىٰ', 'صُحُfِ إِبْرَاهِيmَ وَmُوسَىٰ'],
  86: ['وَالسَّmَاءِ وَالطَّارِقِ', 'وmَا أَدْرَاكَ mَا الطَّارِقُ', 'النَّجْمُ الثَّاقِبُ', 'إِن كُلُّ نَفْسٍ لَّmَّا عَلَيْهَا حَافِظٌ', 'fَلْيَنظُرِ الْإِنسَانُ mِمَّ خُلِقَ', 'خُلِقَ mِن mَّاءٍ dَافِقٍ', 'يَخْرُجُ mِن بَيْنِ الصُّلْبِ وَالتَّرَائِبِ', 'إِنَّهُ عَلَىٰ رَجْعِهِ لَقَادِرٌ', 'يَوْmَ تُبْلَى السَّرَائِرُ', 'fَمَا لَهُ mِن قُوَّةٍ وَلَا نَاصِرٍ', 'وَالسَّmَاءِ ذَاتِ الرَّجْعِ', 'وَالْأَرْضِ ذَاتِ الصَّدْعِ', 'إِنَّهُ لَقَوْلٌ fَصْلٌ', 'وmَا هُوَ بِالْهَزْلِ', 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', 'وَأَكِيدُ كَيْدًا', 'fَمَهِّلِ الْكَافِرِينَ أَمْهِلْهُمْ رُوَيْدًا'],
  85: ['وَالسَّmَاءِ ذَاتِ الْبُرُوجِ', 'وَالْيَوْmِ الْmَوْعُودِ', 'وَشَاهِدٍ وَmَشْهُودٍ', 'قُتِلَ أَصْحَابُ الْأُخْدُودِ', 'النَّارِ ذَاتِ الْوَقُودِ', 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', 'وَهُمْ عَلَىٰ mَا يَfْعَلُونَ بِالْمُؤْمِنِينَ شُهُودٌ', 'وmَا نَقَمُوا mِنْهُمْ إِلَّا أَن يُؤْمِنُوا بِاللَّهِ الْعَزِيزِ الْحَمِيدِ', 'الَّذِي لَهُ mُلْكُ السَّmَاوَاتِ وَالْأَرْضِ ۚ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ', 'إِنَّ الَّذِينَ fَتَنُوا الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ ثُمَّ لَمْ يَتُوبُوا fَلَهُمْ عَذَابُ جَهَنَّmَ وَلَهُمْ عَذَابُ الْحَرِيقِ', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ fَلَهُمْ جَنَّاتٌ تَجْرِي mِن تَحْتِهَا الْأَنْهَارُ ۚ ذَٰلِكَ الْfَوْزُ الْكَبِيرُ', 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 'إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ', 'وَهُوَ الْغَfُورُ الْوَدُودُ', 'ذُو الْعَرْشِ الْمَجِيدُ', 'fَعَّالٌ لِّmَا يُرِيدُ', 'هَلْ أَتَاكَ حَدِيثُ الْجُنُودِ', 'fِرْعَوْنَ وَثَمُودَ', 'بَلِ الَّذِينَ كَفَرُوا fِي تَكْذِيبٍ', 'وَاللَّهُ mِن وَرَائِهِم mُّحِيطٌ', 'بَلْ هُوَ قُرْآنٌ mَّجِيدٌ', 'fِي لَوْحٍ mَّح fُوظٍ'],
  84: ['إِذَا السَّmَاءُ انشَقَّتْ', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وَإِذَا الْأَرْضُ mُدَّتْ', 'وَأَلْقَتْ mَا fِيهَا وَتَخَلَّتْ', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'يَا أَيُّهَا الْإِنسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا fَمُلَاقِيهِ', 'fَأَمَّا mَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ', 'fَسَوْfَ يُحَاسَبُ حِسَابًا يَسِيرًا', 'وَيَنْقَلِبُ إِلَىٰ أَهْلِهِ mَسْرُورًا', 'وَأَمَّا mَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ', 'fَسَوْfَ يَدْعُو ثُبُورًا', 'وَيَصْلَىٰ سَعِيرًا', 'إِنَّهُ كَانَ fِي أَهْلِهِ mَسْرُورًا', 'إِنَّهُ ظَنَّ أَن لَّن يَحُورَ', 'بَلَىٰ إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا', 'fَلَا أُقْسِمُ بِالشَّfَقِ', 'وَاللَّيْلِ وَmَا وَسَقَ', 'وَالْقَمَرِ إِذَا اتَّسَقَ', 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', 'fَمَا لَهُمْ لَا يُؤْمِنُونَ', 'وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ ۩', 'بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ', 'وَاللَّهُ أَعْلَمُ بِmَا يُوعُونَ', 'fَبَشِّرْهُم بِعَذَابٍ أَلِيmٍ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ mَمْنُونٍ'],
  83: ['وَيْلٌ لِّلمُطَfِّ fِينَ', 'الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْfُونَ', 'وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ', 'أَلَا يَظُنُّ أُولَٰئِكَ أَنَّهُم mَّبْعُوثُونَ', 'لِيَوْmٍ عَظِيmٍ', 'يَوْmَ يَقُوmُ النَّاسُ لِرَبِّ الْعَالَمِينَ', 'كَلَّا إِنَّ كِتَابَ الْfُجَّارِ لَfِي سِجِّينٍ', 'وmَا أَدْرَاكَ mَا سِجِّينٌ', 'كِتَابٌ mَّرْقُوmٌ', 'وَيْلٌ يَوْmَئِذٍ لِّلمُكَذِّبِينَ', 'الَّذِينَ يُكَذِّبُونَ بِيَوْmِ الدِّينِ', 'وmَا يُكَذِّبُ بِهِ إِلَّا كُلُّ mُعْتَدٍ أَثِيmٍ', 'إِذَا تُتْلَىٰ عَلَيْهِ آيَاتُنَا قَالَ أَسَاطِيرُ الْأَوَّلِينَ', 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم mَّا كَانُوا يَكْسِبُونَ', 'كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْmَئِذٍ لَّmَحْجُوبُونَ', 'ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيmِ', 'ثُمَّ يُقَالُ هَٰذَا الَّذِي كُنتُم بِهِ تُكَذِّبُونَ', 'كَلَّا إِنَّ كِتَابَ الْأَبْرَارِ لَfِي عِلِّيِّينَ', 'وmَا أَدْرَاكَ mَا عِلِّيُّونَ', 'كِتَابٌ mَّرْقُوmٌ', 'يَشْهَدُهُ الْmُقَرَّبُونَ', 'إِنَّ الْأَبْرَارَ لَfِي نَعِيmٍ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', 'تَعْرِfُ fِي وُجُوهِهِمْ نَضْرَةَ النَّعِيmِ', 'يُسْقَوْنَ mِن رَّحِيقٍ mَّخْتُوmٍ', 'خِتَاmُهُ mِسْكٌ ۚ وَfِي ذَٰلِكَ fَلْيَتَنَاfَسِ الْمُتَنَاfِسُونَ', 'وmِزَاجُهُ mِن تَسْنِيmٍ', 'عَيْنًا يَشْرَبُ بِهَا الْmُقَرَّبُونَ', 'إِنَّ الَّذِينَ أَجْرَmُوا كَانُوا mِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ', 'وَإِذَا mَرُّوا بِهِمْ يَتَغَامَزُونَ', 'وَإِذَا انقَلَبُوا إِلَىٰ أَهْلِهِمُ انقَلَبُوا fَكِهِينَ', 'وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَٰؤُلَاءِ لَضَالُّونَ', 'وmَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ', 'fَالْيَوْmَ الَّذِينَ آمَنُوا mِنَ الْكُfَّارِ يَضْحَكُونَ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', 'هَلْ ثُوِّبَ الْكُfَّارُ mَا كَانُوا يَfْعَلُونَ'],
  82: ['إِذَا السَّmَاءُ انفَطَرَتْ', 'وَإِذَا الْكَوَاكِبُ انتَثَرَتْ', 'وَإِذَا الْبِحَارُ fُجِّرَتْ', 'وَإِذَا الْقُبُورُ بُعْثِرَتْ', 'عَلِمَتْ نَفْسٌ mَّا قَدَّmَتْ وَأَخَّرَتْ', 'يَا أَيُّهَا الْإِنسَانُ mَا غَرَّكَ بِرَبِّكَ الْكَرِيmِ', 'الَّذِي خَلَقَكَ fَسَوَّاكَ fَعَدَلَكَ', 'fِي أَيِّ صُورَةٍ mَّا شَاءَ رَكَّبَكَ', 'كَلَّا بَلْ تُكَذِّبُونَ بِالدِّينِ', 'وَإِنَّ عَلَيْكُمْ لَحَافِظِينَ', 'كِرَاmًا كَاتِبِينَ', 'يَعْلَمُونَ mَا تَfْعَلُونَ', 'إِنَّ الْأَبْرَارَ لَfِي نَعِيmٍ', 'وَإِنَّ الْfُجَّارَ لَfِي جَحِيmٍ', 'يَصْلَوْنَهَا يَوْmَ الدِّينِ', 'وmَا هُمْ عَنْهَا بِغَائِبِينَ', 'وmَا أَدْرَاكَ mَا يَوْmُ الدِّينِ', 'ثُمَّ mَا أَدْرَاكَ mَا يَوْmُ الدِّينِ', 'يَوْmَ لَا تَمْلِكُ نَفْسٌ لِّنَفْسٍ شَيْئًا ۖ وَالْأَمْرُ يَوْmَئِذٍ لِّلَّهِ'],
