// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isJuz30 = level.id === 9;
  const hasReview = level.id >= 1 && level.id <= 4; 
  const isIqra8 = level.id === 8;
  const isIqra1 = level.id === 1;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW' | 'SURAH_SELECT'> (isJuz30 ? 'SURAH_SELECT' : 'SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [reviewPage, setReviewPage] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [showNotification, setShowNotification] = useState(true);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    setShowNotification(false);
    const timeout = setTimeout(() => setShowNotification(true), 10);
    return () => clearTimeout(timeout);
  }, [currentIndex, reviewPage, mode]);

  const activeSurahVerses = useMemo(() => {
    if (!isJuz30 || mode === 'SURAH_SELECT') return [];
    const surah = JUZ_30_DATA[currentIndex];
    return SURAH_VERSES[surah.number] || ["(Ayat sedang dikemaskini)"];
  }, [isJuz30, mode, currentIndex]);

  const handleSurahClick = (idx: number) => {
    setCurrentIndex(idx);
    setMode('SEQUENTIAL');
  };

  const nextLetter = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      if (hasReview) {
        setMode('REVIEW');
        setReviewPage(0);
      } else {
        onFinish();
      }
    }
  };

  const prevLetter = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    } else if (isJuz30) {
      setMode('SURAH_SELECT');
    }
  };

  const nextReviewPage = () => {
    if (reviewPage < reviewGrids.length - 1) {
      setReviewPage(reviewPage + 1);
    } else {
      onFinish();
    }
  };

  const prevReviewPage = () => {
    if (reviewPage > 0) {
      setReviewPage(reviewPage - 1);
    } else {
      setMode('SEQUENTIAL');
      setCurrentIndex(data.length - 1);
    }
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > minSwipeDistance) {
      if (mode === 'SEQUENTIAL') nextLetter();
      else if (mode === 'REVIEW') nextReviewPage();
    } else if (distance < -minSwipeDistance) {
      if (mode === 'SEQUENTIAL') prevLetter();
      else if (mode === 'REVIEW') prevReviewPage();
    }
  };

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Baca ayat Al-Quran ini dengan makhraj dan tartil yang sempurna: ${text}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const handleBoxClick = (text: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(text);
    setTimeout(() => setIsAnimating(null), 400);
  };

  const totalSteps = isJuz30 ? data.length : (hasReview ? data.length + reviewGrids.length : data.length);
  const currentStep = mode === 'SEQUENTIAL' ? currentIndex + 1 : (mode === 'REVIEW' ? data.length + reviewPage + 1 : 0);
  const overallProgress = (currentStep / totalSteps) * 100;

  const colorTheme = useMemo(() => {
    switch(level.id) {
      case 9: return 'amber';
      case 8: return 'rose';
      case 7: return 'fuchsia';
      case 6: return 'violet';
      case 5: return 'indigo';
      default: return 'emerald';
    }
  }, [level.id]);

  const pageTitle = useMemo(() => {
    if (level.id !== 5) return level.title;
    if (currentIndex < 9) return 'Tanda Sukun (Mati)';
    if (currentIndex < 12) return 'Mad Asli (2 Harakat)';
    if (currentIndex < 13) return 'Latihan Mad Asli';
    if (currentIndex < 14) return 'Mad Wajib Muttasil';
    if (currentIndex < 15) return 'Mad Jaiz Munfasil';
    if (currentIndex < 16) return 'Mad Arid Lissukun';
    if (currentIndex < 17) return 'Mad Lazim';
    return 'Latihan Gabungan Mad';
  }, [level.id, currentIndex]);

  const guidance = useMemo(() => {
    if (level.id === 1) return 'Sebut huruf dengan baris di atas secara pendek dan jelas.';
    if (level.id === 2) return 'Perhatikan beza bunyi baris atas (a), bawah (i) dan depan (u).';
    if (level.id === 3) return 'Tanween menghasilkan bunyi "n" di hujung (an, in, un).';
    if (level.id === 5) {
      if (currentIndex < 9) return 'Matikan bunyi huruf yang mempunyai tanda bulat di atasnya.';
      if (currentIndex < 12) return 'Panjangkan bacaan sebanyak 2 harakat apabila bertemu huruf Mad.';
      return 'Perhatikan panjang harakat yang berbeza bagi setiap jenis Mad.';
    }
    if (level.id === 6) return 'Tekan suara pada huruf yang mempunyai tanda sabdu (w).';
    if (level.id === 7) return 'Perhatikan hukum dengung (Nun/Mim mati) dalam sebutan.';
    return null;
  }, [level.id, currentIndex]);

  const reviewGrids = useMemo(() => {
    const letters = IQRA_1_LETTERS;
    const size = 16;
    const grids = [];
    for (let i = 0; i < letters.length; i += size) {
      grids.push(letters.slice(i, i + size));
    }
    return grids;
  }, []);

  if (isJuz30 && mode === 'SURAH_SELECT') {
    return (
      <div className="max-w-4xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-screen">
        <header className="w-full flex justify-between items-center mb-10">
          <button onClick={onBack} className="flex items-center space-x-2 text-gray-400 hover:text-amber-600 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
            <span className="text-sm font-black uppercase tracking-widest">UTAMA</span>
          </button>
          <div className="text-right">
             <h2 className="text-2xl font-black text-gray-800">Juz Amma</h2>
             <p className="text-xs font-bold text-amber-600 uppercase tracking-widest">Pilih Surah (114-78)</p>
          </div>
        </header>
        <div className="w-full grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" dir="rtl">
          {JUZ_30_DATA.map((surah, idx) => (
            <button 
              key={surah.number}
              onClick={() => handleSurahClick(idx)}
              className="group bg-white p-6 rounded-[2rem] border-2 border-transparent hover:border-amber-200 hover:shadow-xl transition-all duration-300 flex items-center justify-between text-right"
            >
              <div className="flex flex-col items-end">
                <span className="arabic-text text-2xl text-gray-900 group-hover:text-amber-700 transition-colors">{surah.name}</span>
                <span className="text-xs font-bold text-gray-400 uppercase tracking-widest group-hover:text-amber-500" dir="ltr">{surah.transliteration}</span>
              </div>
              <div className="w-10 h-10 bg-amber-50 rounded-2xl flex items-center justify-center text-amber-600 font-black text-xs shadow-inner">
                {surah.number}
              </div>
            </button>
          ))}
        </div>
        <Copyright />
      </div>
    );
  }

  if (isJuz30 && mode === 'SEQUENTIAL') {
    const currentSurah = JUZ_30_DATA[currentIndex];
    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-screen bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <header className="w-full flex justify-between items-center mb-12">
          <button onClick={() => setMode('SURAH_SELECT')} className="flex items-center space-x-2 text-gray-300 hover:text-amber-600 transition-colors">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
            <span className="text-xs font-black uppercase tracking-widest">SENARAI</span>
          </button>
          <div className="text-right">
             <h2 className="text-3xl font-black text-gray-900 tracking-tight">{currentSurah.transliteration}</h2>
             <p className="text-[10px] font-black text-amber-500 uppercase tracking-[0.3em]">{currentSurah.translation}</p>
          </div>
        </header>

        <div className="w-full space-y-16" dir="rtl">
           {/* Bismillah Section */}
           <div className="w-full text-center py-10 border-b border-gray-50 mb-10">
              <p className="arabic-text text-5xl text-emerald-950 tracking-[0.05em] leading-[2.5] select-none antialiased">
                {BISMILLAH}
              </p>
           </div>

           {/* Verses with High Legibility Design */}
           <div className="w-full space-y-20">
             {activeSurahVerses.map((verse, vIdx) => (
               <div 
                 key={vIdx}
                 onClick={() => handleBoxClick(verse, vIdx)}
                 className={`group flex flex-col items-center cursor-pointer transition-all duration-500 ${isAnimating === vIdx ? 'scale-95' : 'hover:scale-[1.02]'}`}
               >
                 <div className="relative w-full max-w-5xl text-center">
                    <p className="arabic-text text-5xl sm:text-6xl md:text-7xl text-gray-950 leading-[2.2] tracking-[0.08em] antialiased drop-shadow-sm group-hover:text-emerald-900 transition-colors duration-500">
                      {verse}
                    </p>
                    {isLoadingAudio && isAnimating === vIdx && (
                       <div className="absolute -top-12 left-1/2 -translate-x-1/2">
                          <div className="w-6 h-6 border-2 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                       </div>
                    )}
                 </div>

                 {/* Verse Number Ornament */}
                 <div className="mt-8 flex items-center justify-center">
                    <div className="w-12 h-12 rounded-full border border-amber-200 flex items-center justify-center text-[11px] font-black text-amber-600 bg-amber-50/30 shadow-inner group-hover:border-emerald-300 group-hover:bg-emerald-50 transition-all">
                       {vIdx + 1}
                    </div>
                 </div>
               </div>
             ))}
           </div>
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-8 mt-24 pb-20">
          <button onClick={prevLetter} className="py-6 bg-white border border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-amber-600 hover:border-amber-100 transition-all uppercase tracking-widest text-[10px] shadow-sm">KEMBALI</button>
          <button onClick={nextLetter} className="py-6 bg-amber-600 text-white rounded-[2.5rem] font-black shadow-2xl shadow-amber-100 hover:bg-amber-700 hover:scale-[1.03] active:scale-95 transition-all uppercase tracking-widest text-[10px]">SETERUSNYA</button>
        </div>
        <Copyright />
      </div>
    );
  }

  if (isIqra8) {
    const currentWaqaf = IQRA_8_DATA[currentIndex];
    const isSukarPage = currentIndex >= 6; 

    return (
      <div 
        className="max-w-6xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh] bg-white"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        <div className="w-full flex justify-between items-center mb-6">
          <button onClick={onBack} className="p-2 text-gray-400 hover:text-rose-600 transition-all flex items-center space-x-2">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             <span className="text-sm font-black uppercase tracking-widest">KEMBALI</span>
          </button>
          <div className="flex-1 mx-8 h-1.5 bg-gray-100 rounded-full overflow-hidden">
             <div className="h-full bg-rose-500 transition-all duration-700" style={{ width: `${overallProgress}%` }}></div>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-[10px] font-black text-rose-600 uppercase tracking-[0.2em]">{isSukarPage ? 'IQRA 8 LANJUTAN' : (currentWaqaf.name === 'Sujud Tilawah' ? 'HUKUM SAJDAH' : 'TANDA WAQAF')}</span>
            <span className="text-xs font-bold text-gray-300">{currentStep}/{totalSteps}</span>
          </div>
        </div>

        <div className="w-full flex flex-col items-center space-y-6">
          <div className="w-full max-w-3xl bg-white p-6 rounded-[2.5rem] shadow-sm border border-gray-50 flex flex-col items-center space-y-4 animate-in fade-in zoom-in-95 duration-700">
            <div className="flex items-center space-x-8">
              <div className="w-20 h-20 bg-white border-2 border-rose-50 rounded-3xl flex items-center justify-center text-rose-600 text-5xl arabic-text shadow-sm ring-2 ring-rose-50/20">
                {currentWaqaf.sign}
              </div>
              <div className="text-left space-y-1">
                <h2 className="text-3xl font-black text-emerald-950 leading-none">{currentWaqaf.name}</h2>
                <div className="px-3 py-1 bg-rose-50 text-rose-600 text-[10px] font-black rounded-full border border-rose-100 uppercase tracking-[0.2em] inline-block">
                  {currentWaqaf.name === 'Sujud Tilawah' ? 'SEJADAH' : 'HUKUM BERHENTI'}
                </div>
              </div>
            </div>
            <p className="text-xl text-gray-500 font-medium text-center max-w-xl leading-snug italic border-t border-gray-50 pt-4">
              "{currentWaqaf.rule}"
            </p>
          </div>

          <div className="w-full flex flex-col items-center space-y-12 py-8">
             <div className="w-full flex flex-col items-center space-y-12" dir="rtl">
               {currentWaqaf.examples.map((ex, idx) => (
                 <button 
                   key={idx}
                   onClick={() => handleBoxClick(ex, idx)}
                   disabled={isLoadingAudio}
                   className={`w-full max-w-4xl p-12 bg-white rounded-[3.5rem] border border-transparent shadow-sm hover:shadow-xl hover:border-rose-100 transition-all duration-500 group relative overflow-hidden flex flex-col items-center outline-none ${isAnimating === idx ? 'scale-[0.98] border-rose-300 bg-rose-50/5' : ''}`}
                 >
                    <span className="arabic-text text-4xl sm:text-6xl text-emerald-950 leading-[2.2] tracking-[0.05em] w-full text-center antialiased" style={{ wordSpacing: '8pt' }}>
                      {ex}
                    </span>
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-all duration-300 transform translate-y-2 group-hover:translate-y-0">
                       <div className="flex items-center space-x-2 bg-emerald-50 px-4 py-1.5 rounded-full border border-emerald-100 shadow-sm">
                          <span className="text-[9px] font-black text-emerald-600 uppercase tracking-[0.2em]">DENGAR</span>
                          <svg className="w-3 h-3 text-emerald-600" fill="currentColor" viewBox="0 0 20 20"><path d="M9.383 3.076A1 1 0 0110 4v12a1 1 0 01-1.707.707L4.586 13H2a1 1 0 01-1-1V8a1 1 0 011-1h2.586l3.707-3.707a1 1 0 011.09-.217zM14.657 2.929a1 1 0 011.414 0A9.972 9.972 0 0119 10a9.972 9.972 0 01-2.929 7.071a1 1 0 01-1.414-1.414A7.971 7.971 0 0017 10c0-2.21-.894-4.208-2.343-5.657a1 1 0 010-1.414z"/></svg>
                       </div>
                    </div>
                    {isLoadingAudio && isAnimating === idx && (
                      <div className="absolute top-12 left-12">
                        <div className="w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                      </div>
                    )}
                 </button>
               ))}
             </div>
          </div>
        </div>

        <div className="w-full max-w-xl grid grid-cols-2 gap-6 mt-12 pb-8">
          <button onClick={prevLetter} disabled={currentIndex === 0} className="py-5 bg-white border-2 border-gray-100 rounded-[2.5rem] font-black text-gray-400 hover:text-gray-600 hover:bg-gray-50 disabled:opacity-30 transition-all duration-300 uppercase tracking-[0.2em] text-[10px]">KEMBALI</button>
          <button onClick={nextLetter} className="py-5 bg-rose-600 text-white rounded-[2.5rem] font-black shadow-xl shadow-rose-200 hover:bg-rose-700 hover:scale-[1.03] active:scale-95 transition-all duration-300 uppercase tracking-[0.2em] text-[10px]">{currentIndex === data.length - 1 ? 'SELESAI' : 'SETERUSNYA'}</button>
        </div>
        <Copyright />
      </div>
    );
  }

  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];

  return (
    <div 
      className="max-w-5xl mx-auto p-4 md:p-8 flex flex-col items-center animate-in fade-in slide-in-from-bottom-8 min-h-[70vh]"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <div className="w-full flex justify-between items-center mb-8">
        <button onClick={onBack} className={`p-2 text-gray-400 hover:text-${colorTheme}-600 transition-colors flex items-center space-x-1`}>
           <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           <span className="text-sm font-bold">Batal</span>
        </button>
        <div className="flex-1 mx-4 sm:mx-8 h-2 bg-gray-100 rounded-full overflow-hidden">
           <div className={`h-full bg-${colorTheme}-500 transition-all duration-500`} style={{ width: `${overallProgress}%` }}></div>
        </div>
        <div className="flex flex-col items-end whitespace-nowrap">
          <span className={`text-[10px] font-black text-${colorTheme}-600 uppercase tracking-widest`}>{mode === 'SEQUENTIAL' ? 'Latihan' : 'Review'}</span>
          <span className="text-xs font-bold text-gray-400">{currentStep}/{totalSteps}</span>
        </div>
      </div>

      {mode === 'SEQUENTIAL' ? (
        <div className="w-full flex flex-col items-center space-y-6">
          <div className="text-center space-y-2">
             <h2 className="text-3xl font-black text-gray-800 tracking-tight">{level.id === 5 ? pageTitle : level.title}</h2>
             {guidance && (
               <div className={`max-w-lg mx-auto bg-${colorTheme}-50 border-${colorTheme}-100 p-4 rounded-2xl flex items-start space-x-3 text-left shadow-sm animate-in zoom-in-95 duration-500`}>
                  <div className={`mt-1 flex-shrink-0 w-6 h-6 bg-${colorTheme}-600 rounded-full flex items-center justify-center text-white text-[10px] font-black shadow-lg`}>i</div>
                  <div className={`text-xs sm:text-sm text-${colorTheme}-900 font-medium leading-relaxed`}>
                    <span className="font-bold block mb-0.5">Nota Pintar:</span>
                    {guidance}
                  </div>
               </div>
             )}
          </div>
          <div className={`w-full grid gap-4 ${isIqra1 ? 'grid-cols-1 max-w-lg' : 'grid-cols-2 sm:grid-cols-3 max-w-4xl'}`} dir="rtl">
            {currentItems.map((word, vIdx) => (
              <button 
                key={vIdx}
                onClick={() => handleBoxClick(word as string, vIdx)}
                disabled={isLoadingAudio}
                className={`w-full bg-white shadow-md border-2 border-${colorTheme}-100 text-${colorTheme}-900 flex items-center justify-center arabic-text select-none transition-all duration-300 relative rounded-3xl sm:rounded-[2.5rem] py-8 px-4 sm:py-12 ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400 ring-4 ring-emerald-50' : 'hover:scale-[1.03] active:scale-95 hover:shadow-2xl hover:border-emerald-300'}`}
              >
                {isLoadingAudio && isAnimating === vIdx && (
                  <div className="absolute top-4 right-4"><div className={`w-5 h-5 border-2 border-${colorTheme}-500 border-t-transparent rounded-full animate-spin`}></div></div>
                )}
                <span className={`leading-[1.8] font-black text-center transition-transform duration-300 tracking-[0.05em] ${isAnimating === vIdx ? 'scale-110' : ''} ${isIqra1 ? 'text-[12rem] sm:text-[18rem]' : 'text-3xl sm:text-4xl md:text-5xl'}`}>{word}</span>
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="w-full flex flex-col items-center animate-in zoom-in-95 duration-500">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 w-full max-w-2xl bg-emerald-50 p-6 rounded-[2.5rem] shadow-inner" dir="rtl">
            {reviewGrids[reviewPage]?.map((letter, idx) => (
              <button
                key={`${reviewPage}-${idx}`}
                onClick={() => handleBoxClick(letter, idx)}
                disabled={isLoadingAudio}
                className={`aspect-square bg-white rounded-2xl shadow-sm flex items-center justify-center transition-all duration-300 border-2 border-transparent hover:border-emerald-200 relative ${isAnimating === idx ? 'animate-bounce-click scale-90 border-emerald-400' : 'hover:scale-105 active:scale-95'}`}
              >
                 {isLoadingAudio && isAnimating === idx && (
                  <div className="absolute top-1 right-1"><div className="w-2 h-2 border border-emerald-500 border-t-transparent rounded-full animate-spin"></div></div>
                )}
                <span className={`arabic-text font-black text-3xl leading-[1.2] text-emerald-900 translate-y-1 transition-transform duration-300 ${isAnimating === idx ? 'scale-125' : ''}`}>{letter}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      <div className={`mt-10 transition-all duration-500 transform ${showNotification ? 'opacity-100 scale-100 translate-y-0' : 'opacity-0 scale-90 -translate-y-2'}`}>
        <div className={`px-8 py-3 rounded-full text-xs sm:text-sm font-bold border shadow-lg flex items-center space-x-2 bg-${colorTheme}-100 text-${colorTheme}-800 border-${colorTheme}-200`}>
          <span className={`w-2 h-2 rounded-full animate-pulse bg-${colorTheme}-500`}></span>
          <span>{mode === 'SEQUENTIAL' ? `Halaman ${currentIndex + 1} / ${data.length}` : `Review Halaman ${reviewPage + 1}`}</span>
        </div>
      </div>

      <div className="w-full max-w-2xl grid grid-cols-2 gap-4 mt-8 mb-4">
        <button onClick={mode === 'SEQUENTIAL' ? prevLetter : prevReviewPage} disabled={mode === 'SEQUENTIAL' && currentIndex === 0} className="py-4 sm:py-6 bg-white border-2 border-gray-100 rounded-2xl sm:rounded-3xl font-bold text-gray-500 hover:bg-gray-50 disabled:opacity-30 transition-all duration-300">Kembali</button>
        <button onClick={mode === 'SEQUENTIAL' ? nextLetter : nextReviewPage} className={`py-4 sm:py-6 rounded-2xl sm:rounded-3xl font-bold text-white shadow-xl transition-all duration-300 bg-${colorTheme}-600 shadow-${colorTheme}-200 hover:bg-${colorTheme}-700 hover:scale-[1.02] active:scale-95`}>
          {mode === 'SEQUENTIAL' ? (currentIndex === data.length - 1 ? (hasReview ? 'Mula Ulangkaji' : 'Selesai') : 'Seterusnya') : (reviewPage === reviewGrids.length - 1 ? 'Selesai' : 'Seterusnya')}
        </button>
      </div>
      <Copyright />
    </div>
  );
};

export default PracticeSession;

