import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import Logo from './components/Logo';
import Copyright from './components/Copyright';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [animatingCardId, setAnimatingCardId] = useState<number | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  // Start with only Level 1 unlocked
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]); 

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');

    if (savedProgress) {
      try {
        setUnlockedLevels(JSON.parse(savedProgress));
      } catch (e) { console.error(e); }
    }

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    if (user) {
      localStorage.setItem('advancekids_user', JSON.stringify(user));
    }
  }, [unlockedLevels, user]);

  const handleSplashFinish = () => {
    setAppState(AppState.LOGIN);
  };

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.PROFILE_SETUP);
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelSelect = (level: IqraLevel) => {
    if (!unlockedLevels.includes(level.id) && !user?.isAdmin) return;
    setAnimatingCardId(level.id);
    setTimeout(() => {
      setSelectedLevel(level);
      setAppState(AppState.SUBMENU);
      setAnimatingCardId(null);
    }, 400);
  };

  const handleSubMenuOption = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      setIsFromPracticePath(true);
      setAppState(AppState.PRACTICE);
    } else if (option === 'LEVEL') {
      setAppState(AppState.LEVEL);
    } else {
      setAppState(AppState.QUIZ);
    }
  };

  const unlockNextLevel = () => {
    if (selectedLevel && selectedLevel.id < IQRA_LEVELS.length) {
      const nextId = selectedLevel.id + 1;
      if (!unlockedLevels.includes(nextId)) {
        setUnlockedLevels(prev => [...prev, nextId]);
      }
    }
  };

  const getLevelColorGlow = (id: number) => {
    const colors = [
      'shadow-emerald-200/50', 'shadow-teal-200/50', 'shadow-cyan-200/50',
      'shadow-sky-200/50', 'shadow-indigo-200/50', 'shadow-violet-200/50',
      'shadow-fuchsia-200/50', 'shadow-rose-200/50', 'shadow-amber-200/50'
    ];
    return colors[id - 1] || 'shadow-gray-200/50';
  };

  const getLevelBorder = (id: number) => {
    const borders = [
      'hover:border-emerald-400', 'hover:border-teal-400', 'hover:border-cyan-400',
      'hover:border-sky-400', 'hover:border-indigo-400', 'hover:border-violet-400',
      'hover:border-fuchsia-400', 'hover:border-rose-400', 'hover:border-amber-400'
    ];
    return borders[id - 1] || 'hover:border-gray-400';
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH:
        return <SplashScreen onFinish={handleSplashFinish} />;
      case AppState.LOGIN:
        return <LoginPage onLogin={handleLogin} />;
      case AppState.PROFILE_SETUP:
        return <ProfileSetup onComplete={handleProfileComplete} />;
      case AppState.MENU:
        return (
          <div className="max-w-6xl mx-auto p-6 space-y-12 pb-20 fade-in flex flex-col min-h-screen relative">
            <header className="flex justify-between items-center py-4 relative z-10">
              <div className="flex items-center space-x-4">
                <Logo size="sm" />
                <h1 className="text-xl font-black text-[#1B1C57] tracking-tight">IQRA PINTAR</h1>
              </div>
              <button 
                onClick={() => setAppState(AppState.PROFILE_VIEW)}
                className="flex items-center space-x-3 bg-white p-2 pr-6 rounded-full shadow-lg border border-emerald-50 hover:scale-105 transition-all duration-300"
              >
                <img src={user?.photoURL} alt="avatar" className="w-10 h-10 rounded-full border-2 border-emerald-400 object-cover" />
                <div className="text-left">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Selamat Datang</p>
                  <p className="text-sm font-bold text-gray-800">{user?.name.split(' ')[0]}</p>
                </div>
              </button>
            </header>

            <section className="text-center space-y-4 relative z-10">
              <h2 className="text-4xl md:text-5xl font-black text-[#1B1C57] leading-tight">
                Dunia Ilmu <span className="text-emerald-600 underline decoration-amber-400 decoration-4 underline-offset-8">Berwarna!</span> 🌈
              </h2>
              <p className="text-gray-500 max-w-xl mx-auto font-medium">Setiap tahap adalah pengembaraan baru. Pilih satu dan mula!</p>
            </section>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10 flex-1 relative z-10">
              {IQRA_LEVELS.map((level) => {
                const isUnlocked = unlockedLevels.includes(level.id) || user?.isAdmin;
                const glowClass = getLevelColorGlow(level.id);
                const borderClass = getLevelBorder(level.id);

                return (
                  <button
                    key={level.id}
                    disabled={!isUnlocked}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative p-8 rounded-[3.5rem] text-left transition-all duration-500 group overflow-hidden border-2 ${
                      isUnlocked 
                        ? `bg-white border-transparent shadow-2xl ${glowClass} ${borderClass} hover:-translate-y-3 hover:scale-[1.04]` 
                        : 'bg-gray-50 border-gray-100 opacity-60 cursor-not-allowed'
                    } ${animatingCardId === level.id ? 'scale-90' : ''}`}
                  >
                    {!isUnlocked && (
                      <div className="absolute inset-0 bg-gray-100/60 backdrop-blur-[2px] z-20 flex items-center justify-center">
                         <div className="bg-white/90 p-5 rounded-3xl shadow-xl flex flex-col items-center space-y-2">
                            <span className="text-4xl">🔒</span>
                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Tahap Terkunci</span>
                         </div>
                      </div>
                    )}

                    {/* Colorful Background Element */}
                    {isUnlocked && (
                      <div className={`absolute top-0 right-0 w-32 h-32 ${level.color} opacity-5 rounded-bl-[5rem] -mr-10 -mt-10 group-hover:scale-150 transition-transform duration-700`}></div>
                    )}

                    <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-4xl mb-8 shadow-xl group-hover:rotate-6 transition-all duration-500 ${isUnlocked ? level.color : 'bg-gray-300'} text-white relative z-10`}>
                      {level.icon}
                      {isUnlocked && <div className="absolute inset-0 rounded-[2rem] bg-white/20 animate-ping opacity-20"></div>}
                    </div>

                    <div className="space-y-3 relative z-10">
                      <div className="flex items-center space-x-3">
                        <h3 className={`text-2xl font-black ${isUnlocked ? 'text-[#1B1C57]' : 'text-gray-400'}`}>{level.title}</h3>
                        {isUnlocked && (
                          <div className={`w-2 h-2 rounded-full ${level.color} animate-pulse shadow-sm`}></div>
                        )}
                      </div>
                      <p className={`font-bold tracking-wide uppercase text-[10px] ${isUnlocked ? 'text-emerald-600' : 'text-gray-400'}`}>{level.subtitle}</p>
                      <p className={`text-sm leading-relaxed font-medium ${isUnlocked ? 'text-gray-500' : 'text-gray-300 blur-[0.5px]'}`}>{level.description}</p>
                    </div>

                    {isUnlocked && (
                       <div className="mt-8 flex justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                          <div className={`p-2 rounded-full ${level.color} text-white shadow-lg transform translate-x-4 group-hover:translate-x-0 transition-transform`}>
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M14 5l7 7-7 7"/></svg>
                          </div>
                       </div>
                    )}
                  </button>
                );
              })}
            </div>
            <Copyright />
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && (
          <div className="fade-in">
            <SubMenu 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.MENU)} 
              onSelectOption={handleSubMenuOption} 
            />
          </div>
        );
      case AppState.LEVEL:
        return selectedLevel && (
          <div className="fade-in">
            <LevelDetail 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              showStartButton={true}
              onStartPractice={() => {
                setIsFromPracticePath(true);
                setAppState(AppState.PRACTICE);
              }}
            />
          </div>
        );
      case AppState.PRACTICE:
        return selectedLevel && (
          <div className="fade-in">
            <PracticeSession 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              onFinish={() => setAppState(AppState.QUIZ)} 
            />
          </div>
        );
      case AppState.QUIZ:
        return selectedLevel && (
          <div className="fade-in">
            <Quiz 
              level={selectedLevel} 
              onBack={() => setAppState(AppState.SUBMENU)} 
              onFinish={() => {
                unlockNextLevel();
                setAppState(AppState.MENU);
              }}
            />
          </div>
        );
      case AppState.PROFILE_VIEW:
        return user && (
          <div className="fade-in">
            <ProfileView 
              user={user} 
              unlockedLevels={unlockedLevels} 
              levels={IQRA_LEVELS} 
              onBack={() => setAppState(AppState.MENU)}
              onUpdateUser={(updated) => setUser(updated)}
            />
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen transition-all duration-700 ease-in-out bg-[#F9FBFF]">
      {/* Background Soft Blobs for Menu */}
      {appState === AppState.MENU && (
        <div className="fixed inset-0 pointer-events-none overflow-hidden">
           <div className="absolute top-1/4 -left-20 w-80 h-80 bg-blue-100 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse"></div>
           <div className="absolute top-1/3 -right-20 w-80 h-80 bg-purple-100 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse [animation-delay:2s]"></div>
           <div className="absolute -bottom-20 left-1/2 w-80 h-80 bg-emerald-100 rounded-full mix-blend-multiply filter blur-3xl opacity-30 animate-pulse [animation-delay:4s]"></div>
        </div>
      )}
      {renderContent()}
    </div>
  );
};

