                className={`w-full bg-white shadow-md border-2 border-${colorTheme}-100 text-${colorTheme}-900 flex items-center justify-center arabic-text select-none transition-all duration-300 relative rounded-3xl sm:rounded-[2.5rem] py-8 px-4 sm:py-12 ${isAnimating === vIdx ? 'animate-bounce-click scale-95 border-emerald-400 ring-4 ring-emerald-50' : 'hover:scale-[1.02] active:scale-95 hover:shadow-2xl hover:border-emerald-300'}`}
              >
