import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import Logo from './components/Logo';
import Copyright from './components/Copyright';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  // Levels 1, 2, 3 are free/unlocked by default
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1, 2, 3]); 
  const [isSubscribed, setIsSubscribed] = useState(false);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');
    const savedSub = localStorage.getItem('advancekids_subscribed');

    if (savedProgress) {
      try { setUnlockedLevels(JSON.parse(savedProgress)); } catch (e) {}
    }
    if (savedSub) setIsSubscribed(savedSub === 'true');

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    localStorage.setItem('advancekids_subscribed', isSubscribed.toString());
    if (user) localStorage.setItem('advancekids_user', JSON.stringify(user));
  }, [unlockedLevels, user, isSubscribed]);

  const handleSplashFinish = () => setAppState(AppState.LOGIN);

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.PROFILE_SETUP);
    }
  };

  const handleProfileComplete = (newUser: User) => {
    setUser(newUser);
    setAppState(AppState.MENU);
  };

  const handleLevelSelect = (level: IqraLevel) => {
    const isFree = level.id <= 3;
    const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

    if (isLocked) {
      const confirmSub = window.confirm(`Tahap ${level.title} memerlukan Langganan Premium. Adakah anda ingin melanggan sekarang?`);
      if (confirmSub) {
        setIsSubscribed(true);
        setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        alert("Pendaftaran Premium Berjaya! Semua tahap kini dibuka.");
      }
      return;
    }

    setSelectedLevel(level);
    setAppState(AppState.SUBMENU);
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={handleSplashFinish} />;
      case AppState.LOGIN: return <LoginPage onLogin={handleLogin} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={handleProfileComplete} />;
      case AppState.MENU:
        return (
          <div className="max-w-4xl mx-auto p-4 flex flex-col h-screen overflow-hidden animate-in fade-in duration-500 relative">
            <header className="flex justify-between items-center py-2 relative z-10">
              <div className="flex items-center space-x-3">
                <Logo size="sm" showText={false} />
                <h1 className="text-lg font-black text-[#1B1C57] tracking-tight">IQRA PINTAR</h1>
              </div>
              <button 
                onClick={() => setAppState(AppState.PROFILE_VIEW)}
                className="flex items-center space-x-2 bg-white p-1 pr-4 rounded-full shadow-md border border-gray-100 hover:scale-105 transition-all"
              >
                <img src={user?.photoURL} alt="avatar" className="w-8 h-8 rounded-full border border-emerald-400 object-cover" />
                <p className="text-xs font-bold text-gray-800">{user?.name.split(' ')[0]}</p>
              </button>
            </header>

            <section className="text-center my-2 relative z-10">
              <h2 className="text-2xl font-black text-[#1B1C57]">Dunia Ilmu Berwarna! 🌈</h2>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">Pilih Tahap Anda</p>
            </section>

            <div className="grid grid-cols-3 gap-3 flex-1 my-2 relative z-10 overflow-hidden">
              {IQRA_LEVELS.map((level) => {
                const isFree = level.id <= 3;
                const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

                return (
                  <button
                    key={level.id}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative p-3 rounded-[1.5rem] text-center transition-all duration-300 group border-2 ${
                      isLocked 
                        ? 'bg-gray-50 border-gray-100 opacity-80' 
                        : `bg-white border-transparent shadow-lg hover:border-${level.color.split('-')[1]}-400 active:scale-95`
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl mx-auto mb-1 shadow-md ${isLocked ? 'bg-gray-300' : level.color} text-white`}>
                      {isLocked ? '🔒' : level.icon}
                    </div>
                    <div className="space-y-0.5">
                      <h3 className={`text-[11px] font-black leading-tight ${isLocked ? 'text-gray-400' : 'text-[#1B1C57]'}`}>{level.title}</h3>
                      <p className={`text-[8px] font-bold uppercase tracking-tight ${isLocked ? 'text-gray-400' : 'text-emerald-600'}`}>{isLocked ? 'PREMIUM' : level.subtitle}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="py-2"><Copyright /></div>
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={(opt) => {
          if (opt === 'PRACTICE') { setIsFromPracticePath(true); setAppState(AppState.PRACTICE); }
          else if (opt === 'LEVEL') setAppState(AppState.LEVEL);
          else setAppState(AppState.QUIZ);
        }} />;
      case AppState.LEVEL:
        return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton={true} onStartPractice={() => { setIsFromPracticePath(true); setAppState(AppState.PRACTICE); }} />;
      case AppState.PRACTICE:
        return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.QUIZ:
        return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW:
        return user && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={(updated) => setUser(updated)} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#F9FBFF] h-screen overflow-hidden">
      {appState === AppState.MENU && (
        <div className="fixed inset-0 pointer-events-none opacity-20">
           <div className="absolute top-1/4 -left-10 w-40 h-40 bg-blue-100 rounded-full blur-3xl"></div>
           <div className="absolute bottom-1/4 -right-10 w-40 h-40 bg-emerald-100 rounded-full blur-3xl"></div>
        </div>
      )}
      {renderContent()}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, SURAH_VERSES, BISMILLAH } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isJuz30 = level.id === 9;
  const isIqra1 = level.id === 1;
  const isIqra2 = level.id === 2;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [mode, setMode] = useState<'SEQUENTIAL' | 'REVIEW' | 'SURAH_SELECT'> (isJuz30 ? 'SURAH_SELECT' : 'SEQUENTIAL');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const activeSurahVerses = useMemo(() => {
    if (!isJuz30 || mode === 'SURAH_SELECT') return [];
    const surah = JUZ_30_DATA[currentIndex];
    return SURAH_VERSES[surah.number] || ["(Ayat sedang dikemaskini)"];
  }, [isJuz30, mode, currentIndex]);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else onFinish();
  };

  const prevLetter = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
    else if (isJuz30) setMode('SURAH_SELECT');
  };

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Sebut huruf ini dengan makhraj yang jelas: ${text}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) { console.error(error); } finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(text);
    setTimeout(() => setIsAnimating(null), 300);
  };

  const colorTheme = level.color.split('-')[1];
  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];

  return (
    <div className="max-w-4xl mx-auto p-4 flex flex-col h-screen overflow-hidden animate-in fade-in duration-300">
      <header className="flex justify-between items-center mb-4">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 flex items-center space-x-1">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
          <span className="text-xs font-bold">Batal</span>
        </button>
        <div className="text-center">
          <h2 className="text-xl font-black text-gray-800">{level.title}</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">{level.subtitle}</p>
        </div>
        <div className="w-10"></div>
      </header>

      <div className="flex-1 flex flex-col items-center justify-center space-y-4">
        <div className={`w-full grid gap-4 ${isIqra1 ? 'grid-cols-1 max-w-sm' : 'grid-cols-2 max-w-md'}`} dir="rtl">
          {currentItems.map((word, vIdx) => (
            <button 
              key={vIdx}
              onClick={() => handleBoxClick(word as string, vIdx)}
              className={`w-full aspect-square bg-white shadow-xl border-2 border-${colorTheme}-100 flex items-center justify-center transition-all duration-300 relative rounded-[2rem] ${isAnimating === vIdx ? 'scale-95 border-emerald-400 ring-4 ring-emerald-50' : 'hover:scale-[1.02] active:scale-95'}`}
            >
              <span className={`arabic-text font-black text-center select-none ${isIqra1 ? 'text-[10rem] md:text-[14rem]' : 'text-6xl md:text-8xl'}`}>
                {word}
              </span>
              {isLoadingAudio && isAnimating === vIdx && (
                <div className="absolute top-4 right-4 animate-spin w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>

        <div className="text-center px-6">
           <p className="text-gray-400 text-[10px] font-black uppercase tracking-widest">Halaman {currentIndex + 1} dari {data.length}</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 my-6">
        <button onClick={prevLetter} disabled={currentIndex === 0} className="py-4 bg-white border border-gray-100 rounded-2xl font-black text-xs uppercase tracking-widest text-gray-400 disabled:opacity-30">Kembali</button>
        <button onClick={nextLetter} className={`py-4 ${level.color} text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-${colorTheme}-100`}>
          {currentIndex === data.length - 1 ? 'Selesai' : 'Seterusnya'}
        </button>
      </div>

      <div className="pb-4"><Copyright /></div>
    </div>
  );
};

export default PracticeSession;

