import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Quiz from './components/Quiz';
import Logo from './components/Logo';
import Copyright from './components/Copyright';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [isFromPracticePath, setIsFromPracticePath] = useState(false);

  // Levels 1, 2, 3 are free/unlocked by default
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1, 2, 3]); 
  const [isSubscribed, setIsSubscribed] = useState(false);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');
    const savedSub = localStorage.getItem('advancekids_subscribed');

    if (savedProgress) {
      try { setUnlockedLevels(JSON.parse(savedProgress)); } catch (e) {}
    }
    if (savedSub) setIsSubscribed(savedSub === 'true');

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) {
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        }
      } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    localStorage.setItem('advancekids_subscribed', isSubscribed.toString());
    if (user) localStorage.setItem('advancekids_user', JSON.stringify(user));
  }, [unlockedLevels, user, isSubscribed]);

  const handleSplashFinish = () => setAppState(AppState.LOGIN);

  const handleLogin = (isAdmin?: boolean) => {
    if (isAdmin) {
      const adminUser: User = {
        name: 'Pentadbir Utama',
        email: 'admin@advancekids.com',
        age: 99,
        parentEmail: 'super@advancekids.com',
        photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin',
        isProfileComplete: true,
        isAdmin: true
      };
      setUser(adminUser);
      setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      setAppState(AppState.MENU);
    } else {
      setAppState(AppState.PROFILE_SETUP);
    }
  };

  const handleLevelSelect = (level: IqraLevel) => {
    const isFree = level.id <= 3;
    const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

    if (isLocked) {
      const confirmSub = window.confirm(`Akses Premium Diperlukan! Tahap ${level.title} dan seterusnya hanya untuk ahli Premium. Adakah anda ingin melanggan sekarang?`);
      if (confirmSub) {
        setIsSubscribed(true);
        setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        alert("Pendaftaran Premium Berjaya! Semua tahap kini dibuka. Selamat belajar!");
      }
      return;
    }

    setSelectedLevel(level);
    setAppState(AppState.SUBMENU);
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={handleSplashFinish} />;
      case AppState.LOGIN: return <LoginPage onLogin={handleLogin} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={(u) => { setUser(u); setAppState(AppState.MENU); }} />;
      case AppState.MENU:
        return (
          <div className="max-w-4xl mx-auto p-4 flex flex-col h-screen overflow-hidden animate-in fade-in duration-500 relative">
            <header className="flex justify-between items-center py-2 relative z-10">
              <div className="flex items-center space-x-3">
                <Logo size="sm" showText={false} />
                <h1 className="text-lg font-black text-[#1B1C57] tracking-tight">IQRA PINTAR</h1>
              </div>
              <button 
                onClick={() => setAppState(AppState.PROFILE_VIEW)}
                className="flex items-center space-x-2 bg-white p-1 pr-4 rounded-full shadow-md border border-gray-100 hover:scale-105 transition-all"
              >
                <img src={user?.photoURL} alt="avatar" className="w-8 h-8 rounded-full border border-emerald-400 object-cover" />
                <p className="text-xs font-bold text-gray-800">{user?.name.split(' ')[0]}</p>
              </button>
            </header>

            <section className="text-center my-1 relative z-10">
              <h2 className="text-2xl font-black text-[#1B1C57]">Dunia Ilmu Berwarna! 🌈</h2>
              <p className="text-[9px] text-gray-400 font-black uppercase tracking-[0.2em] mt-0.5">Pilih Tahap Anda</p>
            </section>

            <div className="grid grid-cols-3 gap-3 flex-1 my-2 relative z-10 overflow-hidden px-2">
              {IQRA_LEVELS.map((level) => {
                const isFree = level.id <= 3;
                const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

                return (
                  <button
                    key={level.id}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative p-3 rounded-[1.5rem] text-center transition-all duration-300 group border-2 flex flex-col items-center justify-center ${
                      isLocked 
                        ? 'bg-gray-50 border-gray-100 opacity-80' 
                        : `bg-white border-transparent shadow-lg hover:border-${level.color.split('-')[1]}-400 active:scale-95`
                    }`}
                  >
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-1.5 shadow-md ${isLocked ? 'bg-gray-300' : level.color} text-white`}>
                      {isLocked ? '🔒' : level.icon}
                    </div>
                    <div className="space-y-0.5">
                      <h3 className={`text-[12px] font-black leading-tight ${isLocked ? 'text-gray-400' : 'text-[#1B1C57]'}`}>{level.title}</h3>
                      <p className={`text-[8px] font-black uppercase tracking-tight ${isLocked ? 'text-gray-400' : 'text-emerald-600'}`}>{isLocked ? 'PREMIUM' : level.subtitle}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="py-1"><Copyright /></div>
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && (
          <div className="h-screen overflow-hidden">
            <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={(opt) => {
              if (opt === 'PRACTICE') { setIsFromPracticePath(true); setAppState(AppState.PRACTICE); }
              else if (opt === 'LEVEL') setAppState(AppState.LEVEL);
              else setAppState(AppState.QUIZ);
            }} />
          </div>
        );
      case AppState.LEVEL:
        return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton={true} onStartPractice={() => { setIsFromPracticePath(true); setAppState(AppState.PRACTICE); }} />;
      case AppState.PRACTICE:
        return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.QUIZ:
        return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW:
        return user && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={(updated) => setUser(updated)} />;
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-[#F9FBFF] h-screen overflow-hidden">
      {appState === AppState.MENU && (
        <div className="fixed inset-0 pointer-events-none opacity-20">
           <div className="absolute top-1/4 -left-10 w-40 h-40 bg-blue-100 rounded-full blur-3xl"></div>
           <div className="absolute bottom-1/4 -right-10 w-40 h-40 bg-emerald-100 rounded-full blur-3xl"></div>
        </div>
      )}
      {renderContent()}
    </div>
  );
};

export default App;

