import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, SURAH_VERSES, BISMILLAH } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isJuz30 = level.id === 9;
  const isIqra1 = level.id === 1;
  const isIqra2 = level.id === 2;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const nextLetter = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else onFinish();
  };

  const prevLetter = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
  };

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Sebut huruf hijaiyah ini dengan tajwid yang betul: ${text}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) { console.error(error); } finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number | string) => {
    setIsAnimating(id);
    playTTS(text);
    setTimeout(() => setIsAnimating(null), 300);
  };

  const colorTheme = level.color.split('-')[1];
  const currentItem = data[currentIndex];
  const currentItems = Array.isArray(currentItem) ? currentItem : [currentItem];

  return (
    <div className="max-w-4xl mx-auto p-4 flex flex-col h-screen overflow-hidden animate-in fade-in duration-300">
      <header className="flex justify-between items-center mb-2 pt-2">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 flex items-center space-x-1">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
          <span className="text-[10px] font-black uppercase tracking-widest">Batal</span>
        </button>
        <div className="text-center">
          <h2 className="text-lg font-black text-gray-800">{level.title}</h2>
          <p className="text-[9px] font-bold text-emerald-600 uppercase tracking-widest">{level.subtitle}</p>
        </div>
        <div className="w-8"></div>
      </header>

      <div className="flex-1 flex flex-col items-center justify-center space-y-4 px-4 overflow-hidden">
        <div className={`w-full grid gap-4 ${isIqra1 ? 'grid-cols-1 max-w-xs' : 'grid-cols-2 max-w-md'}`} dir="rtl">
          {currentItems.map((word, vIdx) => (
            <button 
              key={vIdx}
              onClick={() => handleBoxClick(word as string, vIdx)}
              className={`w-full aspect-square bg-white shadow-2xl border-2 border-${colorTheme}-50 flex items-center justify-center transition-all duration-300 relative rounded-[2.5rem] ${isAnimating === vIdx ? 'scale-90 border-emerald-400 ring-8 ring-emerald-50' : 'hover:scale-[1.02] active:scale-95'}`}
            >
              <span className={`arabic-text font-black text-center select-none leading-none translate-y-2 ${isIqra1 ? 'text-[12rem] md:text-[16rem]' : 'text-7xl md:text-9xl'}`}>
                {word}
              </span>
              {isLoadingAudio && isAnimating === vIdx && (
                <div className="absolute top-6 right-6 animate-spin w-6 h-6 border-4 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>

        <div className="text-center">
           <div className="inline-flex items-center space-x-2 bg-gray-50 px-4 py-1.5 rounded-full border border-gray-100">
              <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></div>
              <p className="text-gray-400 text-[9px] font-black uppercase tracking-widest">Halaman {currentIndex + 1} / {data.length}</p>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 my-6 px-4">
        <button onClick={prevLetter} disabled={currentIndex === 0} className="py-5 bg-white border-2 border-gray-100 rounded-3xl font-black text-[10px] uppercase tracking-[0.2em] text-gray-400 disabled:opacity-20 active:bg-gray-50 transition-all">Kembali</button>
        <button onClick={nextLetter} className={`py-5 ${level.color} text-white rounded-3xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl shadow-${colorTheme}-100 active:scale-95 transition-all`}>
          {currentIndex === data.length - 1 ? 'Selesai Latihan' : 'Halaman Seterusnya'}
        </button>
      </div>

      <div className="pb-2"><Copyright /></div>
    </div>
  );
};

