import Copyright from './components/Copyright';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);

  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1, 2, 3]); 
  const [isSubscribed, setIsSubscribed] = useState(false);

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');
    const savedSub = localStorage.getItem('advancekids_subscribed');

    if (savedProgress) {
      try { setUnlockedLevels(JSON.parse(savedProgress)); } catch (e) {}
    }
    if (savedSub) setIsSubscribed(savedSub === 'true');

    if (savedUser) {
      try {
        const u = JSON.parse(savedUser);
        setUser(u);
        if (u.isAdmin) setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
      } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('advancekids_iqra_progress', JSON.stringify(unlockedLevels));
    localStorage.setItem('advancekids_subscribed', isSubscribed.toString());
    if (user) localStorage.setItem('advancekids_user', JSON.stringify(user));
  }, [unlockedLevels, user, isSubscribed]);

  const handleLevelSelect = (level: IqraLevel) => {
    const isFree = level.id <= 3;
    const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

    if (isLocked) {
      const confirmSub = window.confirm(`Tahap Premium! IQRA 4 hingga Juz Amma memerlukan langganan. Ingin melanggan sekarang?`);
      if (confirmSub) {
        setIsSubscribed(true);
        setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
        alert("Pendaftaran Berjaya! Semua tahap dibuka.");
      }
      return;
    }
    setSelectedLevel(level);
    setAppState(AppState.SUBMENU);
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={() => setAppState(AppState.LOGIN)} />;
      case AppState.LOGIN: return <LoginPage onLogin={(isAdmin) => {
        if (isAdmin) {
          const adminUser: User = { name: 'Admin Utama', email: 'admin@advancekids.com', age: 99, parentEmail: 'admin@advancekids.com', photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin', isProfileComplete: true, isAdmin: true };
          setUser(adminUser);
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
          setAppState(AppState.MENU);
        } else setAppState(AppState.PROFILE_SETUP);
      }} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={(u) => { setUser(u); setAppState(AppState.MENU); }} />;
      case AppState.MENU:
        return (
          <div className="flex flex-col h-[100dvh] overflow-hidden bg-white px-4 py-2 animate-in fade-in duration-500">
            <header className="flex justify-between items-center py-2 shrink-0">
              <div className="flex items-center space-x-2">
                <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-black">IK</div>
                <h1 className="text-sm font-black text-[#1B1C57]">IQRA PINTAR</h1>
              </div>
              <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-2 bg-slate-50 p-1 pr-3 rounded-full border border-gray-100">
                <img src={user?.photoURL} alt="p" className="w-6 h-6 rounded-full object-cover" />
                <span className="text-[10px] font-bold text-gray-700">{user?.name.split(' ')[0]}</span>
              </button>
            </header>

            <section className="text-center py-2 shrink-0">
              <h2 className="text-lg font-black text-[#1B1C57] leading-tight">Dunia Ilmu Berwarna! 🌈</h2>
              <p className="text-[8px] text-gray-400 font-black uppercase tracking-widest">Pilih Tahap Anda</p>
            </section>

            <div className="flex-1 grid grid-cols-3 gap-2 py-2 overflow-hidden min-h-0">
              {IQRA_LEVELS.map((level) => {
                const isFree = level.id <= 3;
                const isLocked = !isFree && !isSubscribed && !user?.isAdmin;
                return (
                  <button
                    key={level.id}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative rounded-2xl border flex flex-col items-center justify-center space-y-1 transition-all active:scale-95 ${
                      isLocked ? 'bg-gray-50 border-gray-100 opacity-70' : 'bg-white border-slate-100 shadow-sm'
                    }`}
                  >
                    <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-lg ${isLocked ? 'bg-gray-200' : level.color} text-white`}>
                      {isLocked ? '🔒' : level.icon}
                    </div>
                    <div className="text-center">
                      <h3 className={`text-[10px] font-black leading-tight ${isLocked ? 'text-gray-400' : 'text-slate-800'}`}>{level.title}</h3>
                      <p className={`text-[7px] font-bold truncate px-1 uppercase ${isLocked ? 'text-gray-400' : 'text-emerald-500'}`}>{isLocked ? 'PREMIUM' : level.subtitle}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="shrink-0 pt-1 pb-1 flex justify-center">
              <p className="text-[7px] text-gray-300 font-black uppercase tracking-widest">Advancekids Media • 2025</p>
            </div>
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={(opt) => {
          if (opt === 'PRACTICE') setAppState(AppState.PRACTICE);
          else if (opt === 'LEVEL') setAppState(AppState.LEVEL);
          else setAppState(AppState.QUIZ);
        }} />;
      case AppState.LEVEL:
        return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton={true} onStartPractice={() => setAppState(AppState.PRACTICE)} />;
      case AppState.PRACTICE:
        return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.QUIZ:
        return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW:
        return user && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={(updated) => setUser(updated)} />;
      default: return null;
    }
  };

  return <div className="h-full w-full max-w-md mx-auto relative">{renderContent()}</div>;
};

