import React, { useState, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, JUZ_30_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Decode Utils
const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const [activeItem, setActiveItem] = useState<number | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Sebut huruf ini: ${text}` }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number) => {
    setActiveItem(id);
    playTTS(text);
    setTimeout(() => setActiveItem(null), 300);
  };

  const currentItem = data[currentIndex];
  const items = Array.isArray(currentItem) ? currentItem : [currentItem];
  const isIqra1 = level.id === 1;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-slate-50 animate-in fade-in duration-300">
      {/* Mini Header */}
      <header className="flex justify-between items-center px-4 py-2 shrink-0 border-b bg-white">
        <button onClick={onBack} className="p-2 text-gray-400">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-xs font-bold text-slate-800 leading-none">{level.subtitle}</p>
        </div>
        <div className="w-9"></div>
      </header>

      {/* Main Container */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 min-h-0 overflow-hidden relative">
        <div className={`w-full grid gap-4 ${isIqra1 ? 'grid-cols-1 max-w-[240px]' : 'grid-cols-2 max-w-[320px]'} justify-center`} dir="rtl">
          {items.map((word, idx) => (
            <button
              key={idx}
              onClick={() => handleBoxClick(word as string, idx)}
              className={`aspect-square bg-white shadow-xl border-2 flex items-center justify-center rounded-[2rem] transition-all relative ${
                activeItem === idx ? 'scale-90 border-emerald-400 ring-4 ring-emerald-50' : 'border-slate-100'
              }`}
            >
              <span className={`arabic-text font-black text-center translate-y-2 select-none ${isIqra1 ? 'text-[9rem]' : 'text-5xl'}`}>
                {word}
              </span>
              {isLoadingAudio && activeItem === idx && (
                <div className="absolute top-4 right-4 animate-spin w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>
        <div className="absolute bottom-4 left-0 right-0 text-center">
           <p className="text-[9px] font-black text-gray-300 uppercase tracking-widest">Halaman {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      {/* Nav Buttons */}
      <div className="shrink-0 p-4 grid grid-cols-2 gap-3 bg-white border-t">
        <button 
          onClick={() => currentIndex > 0 && setCurrentIndex(currentIndex - 1)}
          disabled={currentIndex === 0}
          className="py-3 bg-slate-50 border-2 border-slate-100 rounded-xl font-black text-[9px] uppercase tracking-widest text-slate-400 disabled:opacity-30"
        >
          Kembali
        </button>
        <button 
          onClick={() => currentIndex < data.length - 1 ? setCurrentIndex(currentIndex + 1) : onFinish()}
          className={`py-3 ${level.color} text-white rounded-xl font-black text-[9px] uppercase tracking-widest shadow-lg`}
        >
          {currentIndex === data.length - 1 ? 'Selesai Latihan' : 'Halaman Seterusnya'}
        </button>
      </div>
    </div>
  );
};

