                <h1 className="text-xs font-black text-[#1B1C57] tracking-widest uppercase">IQRA PINTAR</h1>
              </div>
              <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-2 bg-slate-50 p-1 pr-3 rounded-full border border-gray-100">
                <img src={user?.photoURL} alt="p" className="w-6 h-6 rounded-full object-cover" />
                <span className="text-[10px] font-bold text-gray-700">{user?.name.split(' ')[0]}</span>
              </button>
            </header>

            <section className="text-center py-2 shrink-0">
              <h2 className="text-xl font-black text-[#1B1C57]">Dunia Ilmu! 🌈</h2>
              <p className="text-[8px] text-gray-400 font-black uppercase tracking-[0.2em]">Pilih Tahap Anda</p>
            </section>

            <div className="flex-1 grid grid-cols-3 gap-2 py-2 overflow-hidden min-h-0">
              {IQRA_LEVELS.map((level) => {
                const isFree = level.id <= 3;
                const isLocked = !isFree && !isSubscribed && !user?.isAdmin;
                return (
                  <button
                    key={level.id}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative rounded-2xl border flex flex-col items-center justify-center transition-all active:scale-95 ${
                      isLocked ? 'bg-gray-50 border-gray-100 opacity-60' : 'bg-white border-slate-100 shadow-sm'
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl mb-1 shadow-md ${isLocked ? 'bg-gray-300' : level.color} text-white`}>
                      {isLocked ? '🔒' : level.icon}
                    </div>
                    <div className="text-center">
                      <h3 className={`text-[10px] font-black leading-tight ${isLocked ? 'text-gray-400' : 'text-slate-800'}`}>{level.title}</h3>
                      <p className={`text-[7px] font-bold px-1 uppercase ${isLocked ? 'text-gray-300' : 'text-emerald-500'}`}>{isLocked ? 'PREMIUM' : level.subtitle}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="shrink-0 pt-2"><Copyright /></div>
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={(opt) => {
          if (opt === 'PRACTICE') setAppState(AppState.PRACTICE);
          else if (opt === 'LEVEL') setAppState(AppState.LEVEL);
          else setAppState(AppState.QUIZ);
        }} />;
      case AppState.LEVEL:
        return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton={true} onStartPractice={() => setAppState(AppState.PRACTICE)} />;
      case AppState.PRACTICE:
        return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.QUIZ:
        return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW:
        return user && <ProfileView user={user} unlockedLevels={[1,2,3]} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={(updated) => setUser(updated)} />;
      default: return null;
    }
  };

  return <div className="h-full w-full max-w-md mx-auto relative">{renderContent()}</div>;
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Decode Utils
const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const [activeItem, setActiveItem] = useState<number | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Sebut kalimah hijaiyah ini: ${text}` }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number) => {
    setActiveItem(id);
    playTTS(text);
    setTimeout(() => setActiveItem(null), 300);
  };

  const currentItem = data[currentIndex];
  const items = Array.isArray(currentItem) ? currentItem : (typeof currentItem === 'string' ? [currentItem] : [currentItem.content]);
  const itemTitle = (typeof currentItem === 'object' && 'title' in currentItem) ? currentItem.title : null;
  const isIqra1 = level.id === 1;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      {/* Mini Header */}
      <header className="flex justify-between items-center px-4 py-2 shrink-0 border-b bg-white">
        <button onClick={onBack} className="p-2 text-gray-400">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest leading-none">{level.subtitle}</p>
        </div>
        <div className="w-9"></div>
      </header>

      {/* Main Container */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 min-h-0 overflow-hidden relative">
        {itemTitle && (
          <div className="absolute top-6 px-6 py-2 bg-emerald-50 rounded-full border border-emerald-100 z-20">
            <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">{itemTitle}</span>
          </div>
        )}

        <div className={`w-full grid gap-4 ${isIqra1 ? 'grid-cols-1 max-w-[240px]' : 'grid-cols-2 max-w-[320px]'} justify-center`} dir="rtl">
          {items.map((word: any, idx) => (
            <button
              key={idx}
              onClick={() => handleBoxClick(word, idx)}
              className={`aspect-square bg-white shadow-xl border-2 flex flex-col items-center justify-center rounded-[2.5rem] transition-all relative ${
                activeItem === idx ? 'scale-90 border-emerald-400 ring-4 ring-emerald-50' : 'border-slate-50 shadow-emerald-50/20'
              }`}
            >
              <span className={`arabic-text font-black text-center select-none leading-none ${isIqra1 ? 'text-[9rem]' : 'text-5xl md:text-6xl'}`}>
                {word}
              </span>
              {isLoadingAudio && activeItem === idx && (
                <div className="absolute top-4 right-4 animate-spin w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>

        <div className="absolute bottom-4 text-center">
           <p className="text-[8px] font-black text-gray-300 uppercase tracking-widest">Halaman {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      {/* Nav Buttons */}
      <div className="shrink-0 p-4 grid grid-cols-2 gap-3 bg-white border-t">
        <button 
          onClick={() => currentIndex > 0 && setCurrentIndex(currentIndex - 1)}
          disabled={currentIndex === 0}
          className="py-4 bg-slate-50 rounded-2xl font-black text-[9px] uppercase tracking-widest text-slate-400 disabled:opacity-30"
        >
          Kembali
        </button>
        <button 
          onClick={() => currentIndex < data.length - 1 ? setCurrentIndex(currentIndex + 1) : onFinish()}
          className={`py-4 ${level.color} text-white rounded-2xl font-black text-[9px] uppercase tracking-widest shadow-lg shadow-emerald-50 active:scale-95`}
        >
          {currentIndex === data.length - 1 ? 'Selesai' : 'Seterusnya'}
        </button>
      </div>
    </div>
  );
};

