import React, { useState, useMemo, useRef } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Decode Utils
const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const [activeItem, setActiveItem] = useState<number | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Sebut kalimah hijaiyah ini dengan tajwid: ${text}` }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number) => {
    setActiveItem(id);
    playTTS(text);
    setTimeout(() => setActiveItem(null), 300);
  };

  const currentItem = data[currentIndex];

  // Logic to determine grid items and titles
  let items: any[] = [];
  let itemTitle: string | null = null;
  let gridCols = 'grid-cols-2';

  if (level.id === 7) {
    // IQRA 7 Specific Logic
    const ruleSet = currentItem as { title: string, items: string[] };
    itemTitle = ruleSet.title;
    items = ruleSet.items;
    gridCols = 'grid-cols-3'; // 3x3 as requested
  } else if (level.id === 1) {
    items = [currentItem];
    gridCols = 'grid-cols-1';
  } else if (Array.isArray(currentItem)) {
    items = currentItem;
    gridCols = 'grid-cols-3';
  } else if (typeof currentItem === 'string') {
    items = [currentItem];
    gridCols = 'grid-cols-1';
  }

  const isIqra1 = level.id === 1;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      {/* Header */}
      <header className="flex justify-between items-center px-4 py-3 shrink-0 border-b bg-white z-20">
        <button onClick={onBack} className="p-2 text-gray-400">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest leading-none truncate max-w-[150px]">{level.subtitle}</p>
        </div>
        <div className="w-9"></div>
      </header>

      {/* Main Container */}
      <div className="flex-1 flex flex-col items-center justify-center p-4 min-h-0 overflow-hidden relative">
        {itemTitle && (
          <div className="absolute top-4 px-6 py-2 bg-emerald-50 rounded-full border border-emerald-100 z-20 shadow-sm">
            <span className="text-[10px] font-black text-emerald-700 uppercase tracking-widest text-center">{itemTitle}</span>
          </div>
        )}

        <div className={`w-full grid ${gridCols} gap-2 sm:gap-4 max-w-sm justify-center py-8`} dir="rtl">
          {items.map((word: any, idx) => (
            <button
              key={idx}
              onClick={() => handleBoxClick(word, idx)}
              className={`bg-white shadow-xl border flex flex-col items-center justify-center transition-all relative rounded-2xl md:rounded-3xl ${
                items.length > 4 ? 'aspect-square p-2' : 'aspect-square p-4'
              } ${
                activeItem === idx ? 'scale-90 border-emerald-400 ring-4 ring-emerald-50 shadow-emerald-100' : 'border-slate-50 shadow-emerald-50/20'
              }`}
            >
              <span className={`arabic-text font-black text-center select-none leading-none ${
                isIqra1 ? 'text-[8rem]' : (items.length > 6 ? 'text-2xl md:text-3xl' : 'text-5xl')
              }`}>
                {word}
              </span>
              {isLoadingAudio && activeItem === idx && (
                <div className="absolute top-2 right-2 animate-spin w-3 h-3 border-2 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>

        <div className="absolute bottom-2 text-center">
           <p className="text-[7px] font-black text-gray-200 uppercase tracking-widest">Halaman {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      {/* Nav Buttons */}
      <div className="shrink-0 p-4 grid grid-cols-2 gap-3 bg-white border-t z-20">
        <button 
          onClick={() => currentIndex > 0 && setCurrentIndex(currentIndex - 1)}
          disabled={currentIndex === 0}
          className="py-4 bg-slate-50 rounded-2xl font-black text-[9px] uppercase tracking-widest text-slate-400 disabled:opacity-30 active:scale-95 transition-all"
        >
          Kembali
        </button>
        <button 
          onClick={() => currentIndex < data.length - 1 ? setCurrentIndex(currentIndex + 1) : onFinish()}
          className={`py-4 ${level.color} text-white rounded-2xl font-black text-[9px] uppercase tracking-widest shadow-lg shadow-emerald-50 active:scale-95 transition-all`}
        >
          {currentIndex === data.length - 1 ? 'Selesai' : 'Seterusnya'}
        </button>
      </div>
    </div>
  );
};

export default PracticeSession;

