import React, { useState, useMemo, useRef, useEffect } from 'react';
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  initialIndex?: number;
  onProgressUpdate?: (index: number) => void;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Decode Utils
const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, initialIndex = 0, onProgressUpdate, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const [activeItem, setActiveItem] = useState<number | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Swipe State
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const data = useMemo(() => {
    switch(level.id) {
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_LETTERS;
    }
  }, [level.id]);

  useEffect(() => {
    if (onProgressUpdate) onProgressUpdate(currentIndex);
  }, [currentIndex, onProgressUpdate]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Sebut kalimah hijaiyah ini dengan tajwid yang betul dan makhraj yang tepat: ${text}` }] }],
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleBoxClick = (text: string, id: number) => {
    setActiveItem(id);
    playTTS(text);
    setTimeout(() => setActiveItem(null), 300);
  };

  const handleNext = () => {
    if (currentIndex < data.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      onFinish();
    }
  };

  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  // Touch handlers for swipe
  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
  };
  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };
  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;

    if (isLeftSwipe) handleNext();
    else if (isRightSwipe) handlePrev();

    touchStartX.current = null;
    touchEndX.current = null;
  };

  const currentItem = data[currentIndex];

  let items: string[] = [];
  let itemTitle: string | null = null;
  let itemTips: string | null = null;
  const isIqra7 = level.id === 7;

  if (isIqra7) {
    const item = currentItem as { title: string, tips: string, items: string[] };
    itemTitle = item.title;
    itemTips = item.tips;
    items = item.items;
  } else if (Array.isArray(currentItem)) {
    items = currentItem as string[];
  } else {
    items = [currentItem as string];
  }

  // Detect if Latihan Sukar (3 items) or Normal (6 items)
  const isSukar = isIqra7 && items.length === 3;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      <style>
        {`
          .quranic-box {
            background: white;
            border: 2px solid #f1f5f9;
            box-shadow: 0 10px 30px -10px rgba(16, 185, 129, 0.1);
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
          }
          .quranic-box:active {
            transform: scale(0.97);
            border-color: #10b981;
          }
          .arabic-typography {
            font-family: 'Amiri', serif;
            letter-spacing: 0.1em;
            line-height: 2;
            -webkit-font-smoothing: antialiased;
            text-rendering: optimizeLegibility;
          }
        `}
      </style>

      {/* Header */}
      <header className="flex justify-between items-center px-4 py-3 shrink-0 border-b bg-white z-20 shadow-sm">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 active:scale-90 transition-all">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest leading-none truncate max-w-[150px]">{level.subtitle}</p>
        </div>
        <div className="w-9"></div>
      </header>

      {/* Main Container - Swipe enabled */}
      <div 
        className="flex-1 flex flex-col items-center justify-start p-4 pt-4 min-h-0 overflow-y-auto relative bg-slate-50/5"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {itemTitle && (
          <div className="sticky top-0 px-8 py-3 bg-white rounded-2xl border-2 border-emerald-500 z-30 shadow-xl shadow-emerald-50 mb-4 w-full max-w-sm text-center">
            <span className="text-[11px] font-black text-emerald-700 uppercase tracking-widest leading-tight">{itemTitle}</span>
          </div>
        )}

        {itemTips && (
          <div className="w-full max-w-sm px-6 py-4 bg-emerald-50 border border-emerald-100 rounded-3xl mb-6 flex items-start space-x-3 text-emerald-900 shadow-sm">
            <span className="text-2xl mt-0.5">📘</span>
            <p className="text-[10px] font-black uppercase tracking-wider leading-relaxed">
              {itemTips}
            </p>
          </div>
        )}

        {/* Dynamic Grid: 3x2 for Normal, 3x1 for Sukar */}
        <div 
          className={`w-full grid ${isSukar ? 'grid-cols-1' : (isIqra7 ? 'grid-cols-2' : 'grid-cols-1')} gap-4 sm:gap-6 max-w-sm justify-center py-2`} 
          dir="rtl"
        >
          {items.map((word, idx) => (
            <button
              key={idx}
              onClick={() => handleBoxClick(word, idx)}
              className={`quranic-box flex items-center justify-center relative rounded-[3.5rem] p-6 ${
                isSukar 
                  ? 'w-full py-12 min-h-[140px]' 
                  : (isIqra7 ? 'aspect-square min-h-[160px]' : (items.length === 1 ? 'w-full aspect-square max-w-[320px]' : 'w-full py-16'))
              } ${
                activeItem === idx ? 'border-emerald-500 ring-4 ring-emerald-50 bg-emerald-50/10' : ''
              }`}
            >
              <span className={`arabic-typography font-bold text-center select-none ${
                isSukar ? 'text-4xl' : (isIqra7 ? 'text-4xl sm:text-5xl' : (items.length === 1 ? 'text-[10rem]' : 'text-8xl'))
              } text-slate-900`}>
                {word}
              </span>
              {isLoadingAudio && activeItem === idx && (
                <div className="absolute top-5 right-5 animate-spin w-4 h-4 border-2 border-emerald-500 border-t-transparent rounded-full"></div>
              )}
            </button>
          ))}
        </div>

        <div className="mt-12 text-center pb-8 opacity-40">
           <p className="text-[8px] font-black text-gray-400 uppercase tracking-[0.6em]">Swipe untuk beralih halaman</p>
           <p className="text-[10px] font-black text-emerald-600 mt-2">HALAMAN {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      {/* Navigation Buttons */}
      <div className="shrink-0 p-6 grid grid-cols-2 gap-4 bg-white border-t z-20 shadow-[0_-10px_40px_rgba(0,0,0,0.03)]">
        <button 
          onClick={handlePrev}
          disabled={currentIndex === 0}
          className="py-5 bg-slate-50 border border-slate-100 rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest text-slate-400 disabled:opacity-30 active:scale-95 transition-all"
        >
          Balik
        </button>
        <button 
          onClick={handleNext}
          className={`py-5 ${level.color} text-white rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-100 active:scale-95 transition-all`}
        >
          {currentIndex === data.length - 1 ? 'Selesai' : 'Lanjut'}
        </button>
      </div>
    </div>
  );
};

