const VideoGenerator: React.FC<VideoGeneratorProps> = ({ level, onBack }) => {
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('Menyediakan skrip video...');
  const [error, setError] = useState<string | null>(null);

  const loadingMessages = [
    "Menyediakan skrip video...",
    "Guru AI sedang melukis babak...",
    "Menjana animasi tajwid...",
    "Menyusun makhraj yang tepat...",
    "Hampir siap, sikit lagi ya!",
    "Mengadun warna keimanan...",
    "Menyiapkan visual yang indah..."
  ];

  useEffect(() => {
    let interval: number;
    if (isLoading) {
      let idx = 0;
      interval = window.setInterval(() => {
        idx = (idx + 1) % loadingMessages.length;
        setLoadingMessage(loadingMessages[idx]);
      }, 5000);
    }
    return () => clearInterval(interval);
  }, [isLoading]);

  const checkApiKey = async () => {
    if (!(window as any).aistudio?.hasSelectedApiKey || !(window as any).aistudio?.openSelectKey) {
      // Fallback if not in the specific environment that provides these methods
      return true;
    }
    const hasKey = await (window as any).aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await (window as any).aistudio.openSelectKey();
      // Proceeding after call as per instructions
      return true;
    }
    return true;
  };

  const generateVideo = async () => {
    setIsLoading(true);
    setError(null);
    setVideoUrl(null);

    try {
      await checkApiKey();
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      let prompt = `A short 3D animated educational video for children learning Islam. 
      The theme is: ${level.title} - ${level.subtitle}. 
      Visual style: Vibrant, colorful, friendly character, clean Islamic art style, glowing Arabic text. 
      Focus: ${level.description}. 
      Scene: A character teaching the proper pronunciation in a magical garden.`;

      if (level.id === 9) {
        prompt = `A cinematic 3D visualization of the majesty of the Quran and Juz Amma. 
        Theme: Juz 30. Peaceful environment, stars in the sky, a small mosque with a glowing crescent moon. 
        Vibrant and spiritual atmosphere for kids.`;
      }

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: prompt,
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const fetchUrl = `${downloadLink}&key=${process.env.API_KEY}`;
        setVideoUrl(fetchUrl);
      } else {
        throw new Error("Gagal mendapatkan link video.");
      }
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setError("Sila pilih kunci API berbayar untuk menjana video.");
        if ((window as any).aistudio?.openSelectKey) {
           await (window as any).aistudio.openSelectKey();
        }
      } else {
        setError("Maaf, penjanaan video gagal. Sila cuba sebentar lagi.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      <header className="flex justify-between items-center px-4 py-3 shrink-0 border-b bg-white z-20 shadow-sm">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 active:scale-90 transition-all">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">AI VIDEO GENERATOR</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest leading-none truncate max-w-[150px]">{level.title}</p>
        </div>
        <div className="w-9"></div>
      </header>

      <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
        {!videoUrl && !isLoading && (
          <div className="space-y-8 animate-in zoom-in-95 duration-500">
            <div className="w-32 h-32 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center text-6xl shadow-inner mx-auto">
              🎬
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 leading-tight">Jana Video Pembelajaran AI</h2>
              <p className="text-sm text-gray-500 max-w-xs mx-auto leading-relaxed">
                Guru AI akan membina video animasi khas untuk membantu anda memahami <strong>{level.title}</strong> dengan lebih seronok!
              </p>
            </div>

            <button 
              onClick={generateVideo}
              className="w-full max-w-sm py-6 bg-emerald-600 text-white rounded-[2rem] font-black text-lg shadow-xl shadow-emerald-100 hover:bg-emerald-700 transition-all active:scale-95 flex items-center justify-center space-x-3"
            >
              <span>Mula Jana Video</span>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
            </button>
            <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest italic">
              *Penjanaan mungkin mengambil masa 1-2 minit.
            </p>
          </div>
        )}

        {isLoading && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="relative">
              <div className="w-24 h-24 border-8 border-emerald-100 border-t-emerald-500 rounded-full animate-spin mx-auto"></div>
              <div className="absolute inset-0 flex items-center justify-center text-2xl">✨</div>
            </div>
            <div className="space-y-2">
              <p className="text-xl font-black text-emerald-600 animate-pulse">{loadingMessage}</p>
              <p className="text-xs text-gray-400 font-medium px-8">Sila jangan tutup halaman ini sementara Guru AI bekerja keras untuk anda.</p>
            </div>
          </div>
        )}

        {error && (
          <div className="space-y-6 animate-in shake duration-500">
            <div className="text-6xl">⚠️</div>
            <p className="text-rose-600 font-bold px-8">{error}</p>
            <button 
              onClick={generateVideo}
              className="px-8 py-4 bg-emerald-600 text-white rounded-2xl font-bold text-sm uppercase tracking-widest shadow-lg"
            >
              Cuba Lagi
            </button>
          </div>
        )}

        {videoUrl && (
          <div className="w-full max-w-2xl space-y-6 animate-in zoom-in-95 duration-700">
            <div className="rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-emerald-50 bg-black aspect-video relative group">
              <video 
                src={videoUrl} 
                controls 
                autoPlay 
                className="w-full h-full object-contain"
              />
            </div>
            <div className="space-y-4">
              <h3 className="text-xl font-black text-slate-900">Video Anda Sudah Siap! 🎉</h3>
              <p className="text-sm text-gray-500 px-4 italic">Semoga video ini membantu anda dalam perjalanan menuntut ilmu Al-Quran.</p>

              <div className="flex space-x-3 px-4">
                <button 
                   onClick={() => window.open(videoUrl, '_blank')}
                   className="flex-1 py-4 bg-slate-100 text-slate-700 rounded-2xl font-bold text-xs uppercase tracking-widest active:scale-95 transition-all"
                >
                  Muat Turun
                </button>
                <button 
