const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [isSubscribed, setIsSubscribed] = useState(false);

  // Track last index per level for "Resume" feature
  const [resumeProgress, setResumeProgress] = useState<Record<number, number>>({});

  useEffect(() => {
    const savedUser = localStorage.getItem('advancekids_user');
    const savedSub = localStorage.getItem('advancekids_subscribed');
    const savedResume = localStorage.getItem('advancekids_resume_progress');

    if (savedSub) setIsSubscribed(savedSub === 'true');
    if (savedUser) {
      try { setUser(JSON.parse(savedUser)); } catch (e) {}
    }
    if (savedResume) {
      try { setResumeProgress(JSON.parse(savedResume)); } catch (e) {}
    }
  }, []);

  const handleLevelSelect = (level: IqraLevel) => {
    const isFree = level.id <= 3;
    const isLocked = !isFree && !isSubscribed && !user?.isAdmin;

    if (isLocked) {
      const confirmSub = window.confirm(`Akses Premium Diperlukan! Tahap ${level.title} memerlukan langganan. Ingin melanggan sekarang?`);
      if (confirmSub) {
        setIsSubscribed(true);
        localStorage.setItem('advancekids_subscribed', 'true');
        alert("Pendaftaran Premium Berjaya!");
      }
      return;
    }
    setSelectedLevel(level);
    setAppState(AppState.SUBMENU);
  };

  const handleUpdateProgress = (levelId: number, index: number) => {
    const newProgress = { ...resumeProgress, [levelId]: index };
    setResumeProgress(newProgress);
    localStorage.setItem('advancekids_resume_progress', JSON.stringify(newProgress));
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={() => setAppState(AppState.LOGIN)} />;
      case AppState.LOGIN: return <LoginPage onLogin={(isAdmin) => {
        if (isAdmin) {
          const u: User = { name: 'Admin Utama', email: 'admin@advancekids.com', age: 99, parentEmail: 'admin@advancekids.com', photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin', isProfileComplete: true, isAdmin: true };
          setUser(u);
          setAppState(AppState.MENU);
        } else setAppState(AppState.PROFILE_SETUP);
      }} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={(u) => { setUser(u); setAppState(AppState.MENU); }} />;
      case AppState.MENU:
        return (
          <div className="flex flex-col h-[100dvh] overflow-hidden bg-white px-4 py-2 animate-in fade-in duration-500">
            <header className="flex justify-between items-center py-2 shrink-0">
              <div className="flex items-center space-x-2">
                <div className="w-8 h-8 bg-emerald-600 rounded-lg flex items-center justify-center text-white font-black text-[10px]">IK</div>
                <h1 className="text-xs font-black text-[#1B1C57] tracking-widest uppercase">IQRA PINTAR</h1>
              </div>
              <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-2 bg-slate-50 p-1 pr-3 rounded-full border border-gray-100">
                <img src={user?.photoURL} alt="p" className="w-6 h-6 rounded-full object-cover" />
                <span className="text-[10px] font-bold text-gray-700">{user?.name.split(' ')[0]}</span>
              </button>
            </header>

            <section className="text-center py-2 shrink-0">
              <h2 className="text-xl font-black text-[#1B1C57]">Dunia Ilmu! 🌈</h2>
              <p className="text-[8px] text-gray-400 font-black uppercase tracking-[0.2em]">Pilih Tahap Anda</p>
            </section>

            <div className="flex-1 grid grid-cols-3 gap-2 py-2 overflow-y-auto min-h-0 no-scrollbar">
              {IQRA_LEVELS.map((level) => {
                const isFree = level.id <= 3;
                const isLocked = !isFree && !isSubscribed && !user?.isAdmin;
                return (
                  <button
                    key={level.id}
                    onClick={() => handleLevelSelect(level)}
                    className={`relative rounded-2xl border flex flex-col items-center justify-center transition-all active:scale-95 py-4 ${
                      isLocked ? 'bg-gray-50 border-gray-100 opacity-60' : 'bg-white border-slate-100 shadow-sm'
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xl mb-1 shadow-md ${isLocked ? 'bg-gray-300' : level.color} text-white`}>
                      {isLocked ? '🔒' : level.icon}
                    </div>
                    <div className="text-center">
                      <h3 className={`text-[10px] font-black leading-tight ${isLocked ? 'text-gray-400' : 'text-slate-800'}`}>{level.title}</h3>
                      <p className={`text-[7px] font-bold px-1 uppercase ${isLocked ? 'text-gray-300' : 'text-emerald-500'}`}>{isLocked ? 'PREMIUM' : level.subtitle}</p>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="shrink-0 pt-2"><Copyright /></div>
          </div>
        );
      case AppState.SUBMENU:
        return selectedLevel && <SubMenu 
          level={selectedLevel} 
          onBack={() => setAppState(AppState.MENU)} 
          onSelectOption={(opt) => {
            if (opt === 'MULA') {
              // Level 9 (Juz 30) skips Detail screen and starts practice directly
              if (selectedLevel.id === 9) {
                setAppState(AppState.PRACTICE);
              } else {
                setAppState(AppState.LEVEL); // AI Guidance
              }
            }
            else if (opt === 'SAMBUNG') setAppState(AppState.PRACTICE); // Resume learning
            else if (opt === 'QUIZ') setAppState(AppState.QUIZ);
          }} 
        />;
      case AppState.LEVEL:
        return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton={true} onStartPractice={() => setAppState(AppState.PRACTICE)} />;
      case AppState.PRACTICE:
        return selectedLevel && <PracticeSession 
          level={selectedLevel} 
          initialIndex={resumeProgress[selectedLevel.id] || 0}
          onProgressUpdate={(idx) => handleUpdateProgress(selectedLevel.id, idx)}
          onBack={() => setAppState(AppState.SUBMENU)} 
          onFinish={() => setAppState(AppState.QUIZ)} 
        />;
      case AppState.QUIZ:
        return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW:
        return user && <ProfileView user={user} unlockedLevels={[1,2,3]} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} onUpdateUser={(updated) => setUser(updated)} />;
      default: return null;
    }
  };

  return <div className="h-full w-full max-w-md mx-auto relative">{renderContent()}</div>;
};

