                  <span className="arabic-text text-8xl text-slate-900">{word}</span>
                </button>
             ))}
          </div>
        )}

        <div className="mt-12 text-center pb-24 opacity-30">
           <p className="text-[8px] font-black text-gray-400 uppercase tracking-[0.6em]">Swipe untuk surah seterusnya</p>
           <p className="text-[10px] font-black text-emerald-600 mt-2">SURAH {currentIndex + 1} / {data.length}</p>
