      }
      return;
    }
    setSelectedLevel(level);
    setAppState(AppState.SUBMENU);
  };

  const handleUpdateProgress = (levelId: number, index: number) => {
    const newProgress = { ...resumeProgress, [levelId]: index };
    setResumeProgress(newProgress);
