                <div className="flex flex-col">
                  <h1 className="text-sm font-extrabold text-slate-900 tracking-tight leading-none uppercase">IQRA <span className="text-teal-600 lowercase font-bold">pintar</span></h1>
                  <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-1">by Advancekids Media</p>
                </div>
              </div>
              <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-2 bg-slate-50 p-1 pr-3 rounded-full border border-slate-100 active:scale-95 transition-transform">
                <img src={user?.photoURL} alt="p" className="w-7 h-7 rounded-full object-cover border-2 border-white shadow-sm" />
                <span className="text-[10px] font-black text-slate-700 uppercase tracking-tight">{user?.name.split(' ')[0]}</span>
