import React, { useState, useMemo, useRef, useEffect } from 'react';
import { IQRA_1_DATA, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, SURAH_CONTENT_MAP } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  initialIndex?: number;
  onProgressUpdate?: (index: number) => void;
  onBack: () => void;
  onFinish: () => void;
}

const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, initialIndex = 0, onProgressUpdate, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const data = useMemo(() => {
    switch(level.id) {
      case 1: return IQRA_1_DATA;
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_DATA;
    }
  }, [level.id]);

  useEffect(() => {
    if (onProgressUpdate) onProgressUpdate(currentIndex);
  }, [currentIndex, onProgressUpdate]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Bacakan ayat Al-Quran ini dengan taranum yang merdu: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleNext = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else onFinish();
  };

  const handlePrev = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
  };

  const onTouchStart = (e: React.TouchEvent) => touchStartX.current = e.targetTouches[0].clientX;
  const onTouchMove = (e: React.TouchEvent) => touchEndX.current = e.targetTouches[0].clientX;
  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > minSwipeDistance) handleNext();
    else if (distance < -minSwipeDistance) handlePrev();
    touchStartX.current = touchEndX.current = null;
  };

  const isJuz30 = level.id === 9;
  const isIqra8 = level.id === 8;
  const isBasicLevel = level.id >= 1 && level.id <= 3;
  const currentItem = data[currentIndex];
  const currentSurah = isJuz30 ? currentItem as any : null;
  const surahText = isJuz30 ? (SURAH_CONTENT_MAP[currentSurah.number] || "Teks surah sedang dikemaskini...") : null;
  const waqafItem = isIqra8 ? currentItem as any : null;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      <header className="flex justify-between items-center px-4 py-3 shrink-0 border-b bg-white z-20 shadow-sm">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 active:scale-90 transition-all">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[9px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest leading-none truncate max-w-[150px]">
            {isJuz30 ? currentSurah.transliteration : level.subtitle}
          </p>
        </div>
        <div className="w-9"></div>
      </header>

      <div 
        className="flex-1 flex flex-col items-center justify-center p-4 overflow-y-auto no-scrollbar"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {isJuz30 ? (
          <div className="w-full max-w-lg space-y-6 animate-in slide-in-from-bottom-8 duration-500">
             <div className="text-center space-y-2">
                <h3 className="text-2xl font-black text-slate-900 tracking-tight uppercase">{currentSurah.transliteration}</h3>
                <p className="text-[10px] text-emerald-600 font-bold uppercase tracking-widest">{currentSurah.translation} • {currentSurah.verses} Ayat</p>
                <div className="h-0.5 w-12 bg-emerald-50 mx-auto rounded-full mt-2"></div>
                <p className="text-[9px] font-black text-emerald-400 uppercase tracking-[0.4em] pt-2">بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ</p>
             </div>

             <div className="bg-white rounded-[2.5rem] p-6 sm:p-8 shadow-2xl shadow-emerald-50/50 border-2 border-slate-50 relative group">
                <button 
                  onClick={() => playTTS(surahText!)}
                  className="absolute top-4 right-4 p-3 bg-emerald-50 text-emerald-600 rounded-2xl hover:bg-emerald-100 transition-colors z-10"
                >
                  {isLoadingAudio ? <div className="w-4 h-4 border-2 border-emerald-600 border-t-transparent rounded-full animate-spin"></div> : <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z"/></svg>}
                </button>
                <p className="arabic-text text-xl sm:text-2xl text-slate-900 leading-[2.8] text-center antialiased" dir="rtl">
                   {surahText}
                </p>
             </div>
          </div>
        ) : isIqra8 ? (
          <div className="w-full max-w-lg space-y-6 animate-in slide-in-from-bottom-8 duration-500">
            <div className="text-center space-y-3">
                <div className="inline-flex items-center justify-center w-14 h-14 bg-rose-500 text-white rounded-[1.5rem] text-3xl font-black mb-1 shadow-lg border-4 border-white">
                  {waqafItem.sign !== '📖' ? waqafItem.sign : '🎯'}
                </div>
                <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">{waqafItem.name}</h3>
                <div className="bg-emerald-50/80 border-2 border-emerald-100 p-5 rounded-[2rem] shadow-sm relative overflow-hidden group">
                  <div className="absolute top-0 left-0 w-1 h-full bg-emerald-400"></div>
                  <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1 text-left">Penerangan Hukum:</p>
                  <p className="text-[11px] text-slate-700 font-bold leading-relaxed text-left">{waqafItem.rule}</p>
                </div>
             </div>
             <div className="space-y-3 pb-24">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest pl-2">Latihan Sebutan:</p>
                {waqafItem.items.map((ex: string, i: number) => (
                  <button 
                    key={i} 
                    onClick={() => playTTS(ex)}
                    className="w-full bg-white rounded-[2rem] p-6 border-2 border-slate-50 shadow-sm active:scale-98 transition-all text-center group hover:border-emerald-100 hover:shadow-md"
                  >
                    <span className="arabic-text text-xl sm:text-2xl text-slate-900 leading-relaxed block" dir="rtl">{ex}</span>
                  </button>
                ))}
             </div>
          </div>
        ) : isBasicLevel ? (
          <div className={`w-full max-w-sm grid ${currentItem.length > 3 ? 'grid-cols-3' : 'grid-cols-1'} gap-4 sm:gap-6 justify-center py-2 animate-in zoom-in-95 duration-500`} dir="rtl">
             {currentItem.map((word: string, idx: number) => (
                <button
                  key={idx}
                  onClick={() => playTTS(word)}
                  className={`bg-white rounded-[1.5rem] sm:rounded-[2.5rem] flex items-center justify-center border-2 border-teal-50 shadow-xl active:scale-90 transition-all aspect-square group hover:border-teal-300 hover:shadow-teal-100/50`}
                >
                  <span className={`arabic-text ${currentItem.length > 3 ? 'text-4xl sm:text-6xl' : 'text-8xl sm:text-[10rem]'} text-slate-900 leading-none antialiased group-hover:scale-110 transition-transform`}>
                    {word}
                  </span>
                </button>
             ))}
          </div>
        ) : (
          <div className="w-full grid grid-cols-1 gap-6 max-w-sm justify-center py-2" dir="rtl">
             {(Array.isArray(data[currentIndex]) ? data[currentIndex] as string[] : [data[currentIndex] as string]).map((word, idx) => (
                <button
                  key={idx}
                  onClick={() => playTTS(word)}
                  className="bg-white rounded-[3rem] p-10 border-2 border-slate-50 shadow-xl active:scale-95 transition-all"
                >
                  <span className="arabic-text text-8xl text-slate-900">{word}</span>
                </button>
             ))}
          </div>
        )}

        <div className="mt-12 text-center pb-24 opacity-30 shrink-0">
           <p className="text-[8px] font-black text-gray-400 uppercase tracking-[0.6em]">Swipe untuk seterusnya</p>
           <p className="text-[10px] font-black text-emerald-600 mt-2">HALAMAN {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      <div className="shrink-0 p-6 flex justify-between items-center bg-white border-t z-20 shadow-[0_-10px_40px_rgba(0,0,0,0.03)]">
        <button 
          onClick={handlePrev} 
          disabled={currentIndex === 0} 
          className="w-[30%] py-5 bg-slate-50 border border-slate-100 rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest text-slate-400 disabled:opacity-30 active:scale-90 transition-transform"
        >
          Balik
        </button>
        <button 
          onClick={handleNext} 
          className={`w-[60%] py-5 ${level.color} text-white rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-100 active:scale-90 transition-transform flex items-center justify-center space-x-2`}
        >
          <span>{currentIndex === data.length - 1 ? 'Selesai' : 'Lanjut'}</span>
          {currentIndex !== data.length - 1 && (
            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7"/></svg>
          )}
        </button>
      </div>
    </div>
  );
};

