import React, { useState, useMemo, useRef, useEffect } from 'react';
import { IQRA_1_DATA, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_30_DATA, SURAH_CONTENT_MAP } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

interface PracticeSessionProps {
  level: IqraLevel;
  initialIndex?: number;
  onProgressUpdate?: (index: number) => void;
  onBack: () => void;
  onFinish: () => void;
}

const decode = (base64: string) => {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
};

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, initialIndex = 0, onProgressUpdate, onBack, onFinish }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const data = useMemo(() => {
    switch(level.id) {
      case 1: return IQRA_1_DATA;
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      case 9: return JUZ_30_DATA;
      default: return IQRA_1_DATA;
    }
  }, [level.id]);

  useEffect(() => {
    if (onProgressUpdate) onProgressUpdate(currentIndex);
  }, [currentIndex, onProgressUpdate]);

  const playTTS = async (text: string) => {
    if (isLoadingAudio || text.includes('IQRA')) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Bacakan dengan jelas: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) {} finally { setIsLoadingAudio(false); }
  };

  const handleNext = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else onFinish();
  };

  const handlePrev = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
  };

  const onTouchStart = (e: React.TouchEvent) => touchStartX.current = e.targetTouches[0].clientX;
  const onTouchMove = (e: React.TouchEvent) => touchEndX.current = e.targetTouches[0].clientX;
  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > minSwipeDistance) handleNext();
    else if (distance < -minSwipeDistance) handlePrev();
    touchStartX.current = touchEndX.current = null;
  };

  const isJuz30 = level.id === 9;
  const isIqra8 = level.id === 8;
  const isBasicLevel = level.id >= 1 && level.id <= 3;
  const currentItem = data[currentIndex];

  // Handling special cases
  const isTitleCard = Array.isArray(currentItem) && currentItem.length === 1 && currentItem[0].includes('IQRA');
  const currentSurah = isJuz30 ? currentItem as any : null;
  const surahText = isJuz30 ? (SURAH_CONTENT_MAP[currentSurah.number] || "Teks surah...") : null;
  const waqafItem = isIqra8 ? currentItem as any : null;

  return (
    <div className="flex flex-col h-[100dvh] overflow-hidden bg-white animate-in fade-in duration-300">
      <header className="flex justify-between items-center px-5 py-4 shrink-0 border-b bg-white z-20 shadow-sm">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 active:scale-90 transition-all">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-none mb-1">{level.title}</h2>
          <p className="text-[11px] font-bold text-emerald-600 uppercase tracking-widest leading-none truncate max-w-[160px]">
            {isJuz30 ? currentSurah.transliteration : level.subtitle}
          </p>
        </div>
        <div className="w-10"></div>
      </header>

      <div 
        className="flex-1 flex flex-col items-center justify-center p-6 overflow-hidden relative"
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {isTitleCard ? (
          <div className="animate-in zoom-in-90 duration-500 flex flex-col items-center">
            <div className="p-16 sm:p-24 border-8 border-emerald-500 rounded-[4rem] bg-white shadow-2xl">
              <h1 className="text-6xl sm:text-8xl font-black text-emerald-950 uppercase tracking-[0.2em]">{currentItem[0]}</h1>
            </div>
            <p className="mt-12 text-sm font-black text-emerald-600 uppercase tracking-[0.4em] animate-pulse">Sila klik 'Lanjut'</p>
          </div>
        ) : isJuz30 ? (
          <div className="w-full max-w-lg space-y-6 animate-in slide-in-from-bottom-8 duration-500 relative z-10 text-center">
             <h3 className="text-3xl font-black text-slate-900 tracking-tight uppercase">{currentSurah.transliteration}</h3>
             <div className="bg-white rounded-[3rem] p-8 shadow-2xl border-4 border-slate-50">
                <p className="arabic-text text-3xl text-slate-900 leading-[2.5]" dir="rtl">{surahText}</p>
             </div>
          </div>
        ) : isBasicLevel ? (
          <div className="w-full flex flex-col items-center justify-center h-full">
            <div className={`grid ${(currentItem as string[]).length > 1 ? 'grid-cols-3' : 'grid-cols-1'} gap-6 sm:gap-10 w-full max-w-sm justify-center py-4 animate-in zoom-in-95 duration-500`} dir="rtl">
               {(currentItem as string[]).map((word: string, idx: number) => (
                  <button
                    key={idx}
                    onClick={() => playTTS(word)}
                    className={`bg-white rounded-[2rem] sm:rounded-[3rem] flex items-center justify-center border-[6px] border-emerald-50 shadow-2xl active:scale-90 transition-all aspect-square group hover:border-emerald-400 relative overflow-hidden`}
                  >
                    <span className={`arabic-text ${(currentItem as string[]).length > 3 ? 'text-6xl sm:text-7xl' : 'text-[10rem] sm:text-[14rem]'} text-slate-900 leading-none antialiased group-hover:scale-105 transition-transform`}>
                      {word}
                    </span>
                  </button>
               ))}
            </div>
            {(currentItem as string[]).length === 9 && (
              <div className="mt-12 px-8 py-3 bg-emerald-600 text-white rounded-full text-xs font-black uppercase tracking-[0.3em] shadow-xl animate-bounce">
                Halaman Rawak 3x3
              </div>
            )}
          </div>
        ) : isIqra8 ? (
          <div className="w-full max-w-lg space-y-6 text-center animate-in zoom-in-95 duration-500">
             <div className="inline-flex items-center justify-center w-20 h-20 bg-rose-600 text-white rounded-3xl text-5xl font-black shadow-xl mb-4">{waqafItem.sign}</div>
             <div className="bg-white rounded-[3rem] p-8 border-4 border-slate-50 shadow-xl overflow-y-auto max-h-[50vh] no-scrollbar">
                {waqafItem.items.map((ex: string, i: number) => (
                  <button key={i} onClick={() => playTTS(ex)} className="w-full p-6 mb-4 bg-emerald-50/30 rounded-2xl hover:bg-emerald-50 transition-colors">
                    <span className="arabic-text text-2xl text-slate-900 leading-relaxed block" dir="rtl">{ex}</span>
                  </button>
                ))}
             </div>
          </div>
        ) : (
          <div className="w-full flex justify-center animate-in zoom-in-95 duration-500" dir="rtl">
             {(Array.isArray(currentItem) ? currentItem : [currentItem]).map((word: any, idx: number) => (
                <button
                  key={idx}
                  onClick={() => playTTS(word as string)}
                  className="bg-white rounded-[4rem] p-16 border-[8px] border-emerald-50 shadow-2xl active:scale-95 transition-all hover:border-emerald-300"
                >
                  <span className="arabic-text text-9xl sm:text-[12rem] text-slate-900">{word}</span>
                </button>
             ))}
          </div>
        )}

        <div className="absolute bottom-6 left-0 right-0 text-center opacity-30 select-none">
           <p className="text-[10px] font-black text-emerald-600 mt-2 uppercase tracking-widest">HALAMAN {currentIndex + 1} / {data.length}</p>
        </div>
      </div>

      <div className="shrink-0 p-8 flex justify-between items-center bg-white border-t z-20 shadow-[0_-15px_45px_rgba(0,0,0,0.05)]">
        <button 
          onClick={handlePrev} 
          disabled={currentIndex === 0} 
          className="w-[32%] py-6 bg-slate-50 border border-slate-100 rounded-[2.5rem] font-black text-[12px] uppercase tracking-widest text-slate-400 disabled:opacity-30 active:scale-90 transition-transform"
        >
          Balik
        </button>
        <button 
          onClick={handleNext} 
          className={`w-[62%] py-6 ${level.color} text-white rounded-[2.5rem] font-black text-[12px] uppercase tracking-widest shadow-2xl shadow-emerald-100 active:scale-90 transition-transform flex items-center justify-center space-x-3`}
        >
          <span>{currentIndex === data.length - 1 ? 'Selesai' : 'Lanjut'}</span>
          {currentIndex !== data.length - 1 && (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M9 5l7 7-7 7"/></svg>
          )}
        </button>
      </div>
    </div>
  );
};

