import React, { useState, useEffect, useMemo, useRef } from 'react';
import { IQRA_1_DATA, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA } from '../constants';
import { IqraLevel } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
import Copyright from './Copyright';

interface PracticeSessionProps {
  level: IqraLevel;
  onBack: () => void;
  onFinish: () => void;
}

// Audio Utils
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const PracticeSession: React.FC<PracticeSessionProps> = ({ level, onBack, onFinish }) => {
  const isIqra8 = level.id === 8;
  const isGridLevel = level.id >= 1 && level.id <= 3;

  const data = useMemo(() => {
    switch(level.id) {
      case 1: return IQRA_1_DATA;
      case 2: return IQRA_2_DATA;
      case 3: return IQRA_3_DATA;
      case 4: return IQRA_4_DATA;
      case 5: return IQRA_5_DATA;
      case 6: return IQRA_6_DATA;
      case 7: return IQRA_7_DATA;
      case 8: return IQRA_8_DATA;
      default: return IQRA_1_DATA;
    }
  }, [level.id]);

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState<number | string | null>(null);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);
  const minSwipeDistance = 50;

  const nextPage = () => {
    if (currentIndex < data.length - 1) setCurrentIndex(currentIndex + 1);
    else onFinish();
  };

  const prevPage = () => {
    if (currentIndex > 0) setCurrentIndex(currentIndex - 1);
  };

  const onTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.targetTouches[0].clientX;
    touchEndX.current = null;
  };

  const onTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.targetTouches[0].clientX;
  };

  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > minSwipeDistance) nextPage();
    else if (distance < -minSwipeDistance) prevPage();
  };

  const playTTS = async (letter: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: (process.env as any).API_KEY });
      const prompt = `Sebutkan dengan makhraj yang jelas: ${letter}`;
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        if (!audioCtxRef.current) {
          audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const ctx = audioCtxRef.current;
        const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.start();
      }
    } catch (error) {
      console.error("TTS Error:", error);
    } finally {
      setIsLoadingAudio(false);
    }
  };

  const currentItem = data[currentIndex];
  const items = Array.isArray(currentItem) ? currentItem : (isIqra8 ? (currentItem as any).examples : [currentItem]);

  const progress = ((currentIndex + 1) / data.length) * 100;

  return (
    <div 
      className="max-w-6xl mx-auto flex flex-col h-[100dvh] bg-white animate-in fade-in duration-500 overflow-hidden"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      {/* Header */}
      <header className="px-6 py-4 flex justify-between items-center border-b">
        <button onClick={onBack} className="p-2 text-gray-400 hover:text-emerald-600 transition-colors">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center">
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{level.title}</p>
          <h2 className="text-emerald-600 font-bold text-sm tracking-widest uppercase">{level.subtitle}</h2>
        </div>
        <div className="w-10"></div>
      </header>

      {/* Progress Bar */}
      <div className="w-full h-1 bg-gray-50">
        <div className="h-full bg-emerald-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
      </div>

      {/* Main Content Area - CENTERED */}
      <main className="flex-1 flex flex-col items-center justify-center p-6 relative">
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[radial-gradient(#10b981_1px,transparent_1px)] [background-size:32px_32px]"></div>

        <div className="w-full max-w-lg flex flex-col items-center justify-center animate-in zoom-in-95 duration-500">
          {isIqra8 ? (
             <div className="w-full space-y-8">
                <div className="flex flex-col items-center text-center space-y-4">
                  <div className="w-20 h-20 bg-rose-600 text-white rounded-3xl flex items-center justify-center text-5xl arabic-text shadow-xl">
                    {(currentItem as any).sign}
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 uppercase">{(currentItem as any).name}</h3>
                  <p className="bg-rose-50 text-rose-700 p-4 rounded-2xl text-sm font-bold border border-rose-100">{(currentItem as any).rule}</p>
                </div>
                <div className="space-y-4" dir="rtl">
                   {(currentItem as any).examples.map((ex: string, i: number) => (
                     <button key={i} onClick={() => playTTS(ex)} className="w-full bg-white p-6 rounded-3xl border-2 border-gray-100 shadow-sm hover:border-rose-400 text-right active:scale-95 transition-all">
                       <span className="arabic-text text-3xl leading-relaxed">{ex}</span>
                     </button>
                   ))}
                </div>
             </div>
          ) : (
            <div className={`grid ${items.length > 3 ? 'grid-cols-3' : 'grid-cols-1'} gap-4 sm:gap-8 w-full justify-center`} dir="rtl">
              {items.map((word: string, idx: number) => (
                <button
                  key={idx}
                  onClick={() => {
                    setIsAnimating(idx);
                    playTTS(word);
                    setTimeout(() => setIsAnimating(null), 400);
                  }}
                  className={`bg-white rounded-[2rem] sm:rounded-[3rem] aspect-square flex items-center justify-center border-4 border-emerald-50 shadow-2xl transition-all duration-300 relative group overflow-hidden ${isAnimating === idx ? 'scale-90 border-emerald-400 bg-emerald-50' : 'hover:border-emerald-200 hover:scale-[1.02]'}`}
                >
                  <span className={`arabic-text font-bold text-slate-900 transition-transform duration-300 ${items.length > 1 ? 'text-6xl sm:text-8xl' : 'text-9xl sm:text-[14rem]'} ${isAnimating === idx ? 'scale-110' : ''}`}>
                    {word}
                  </span>
                  {isLoadingAudio && isAnimating === idx && (
                    <div className="absolute top-4 right-4">
                      <div className="w-6 h-6 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
                    </div>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>
      </main>

      {/* Footer Navigation */}
      <footer className="p-8 flex justify-between items-center bg-white border-t">
        <button 
          onClick={prevPage} 
          disabled={currentIndex === 0} 
          className="w-[32%] py-5 bg-gray-50 border border-gray-100 rounded-[2rem] font-black text-xs uppercase tracking-widest text-gray-400 disabled:opacity-30 active:scale-90 transition-transform"
        >
          Balik
        </button>
        <button 
          onClick={nextPage} 
          className="w-[62%] py-5 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-100 active:scale-90 transition-transform flex items-center justify-center space-x-3"
        >
          <span>{currentIndex === data.length - 1 ? 'Selesai' : 'Seterusnya'}</span>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7"/></svg>
        </button>
      </footer>
    </div>
  );
};

export default PracticeSession;

