      letters: ['ت', 'ث', 'ج', 'د', 'ذ', 'ز', 'س', 'ش', 'ص', 'ض', 'ط', 'ظ', 'ف', 'ق', 'ك'],
      color: 'indigo',
      examples: ['مَنْ دَخَلَهُ', 'مَنْ تَبِعَ', 'قِنْوَانٌ دَانِيَةٌ', 'مَنْ صَبَرَ', 'أَنْدَادًا', 'عَنْ صَلَاتِهِمْ']
    },
    {
      title: '6. Hukum Mim Mati (مْ)',
