    },
    {
      title: '7. Idgham Mimi',
      desc: 'Apabila Mim Mati (مْ) bertemu huruf Mim (م). Dibaca dengan DENGUNG sempurna.',
      letters: ['م bertemu م'],
      color: 'cyan',
      examples: ['عَلَيْهِمْ مُّؤْصَدَةٌ', 'لَهُمْ مَّا', 'كَمْ مِنْ', 'أَمْ مَنْ', 'فِي قُلُوبِهِم مَّرَضٌ', 'أَطْعَمَهُم مِّن']
    },
