    }
  ];

  const totalSteps = sections.length * 2;
  const currentSectionIndex = Math.floor(currentStep / 2);
  const isDetailStep = currentStep % 2 === 0;
  const currentSection = sections[currentSectionIndex];

  const next = () => { if (currentStep < totalSteps - 1) setCurrentStep(s => s + 1); else onBack(); };
  const prev = () => { if (currentStep > 0) setCurrentStep(s => s - 1); else onBack(); };

  const onTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.targetTouches[0].clientX; };
  const onTouchMove = (e: React.TouchEvent) => { touchEndX.current = e.targetTouches[0].clientX; };
  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > 50) next();
    else if (distance < -50) prev();
  };

  const progress = ((currentStep + 1) / totalSteps) * 100;

  return (
    <div 
      className="fixed inset-0 bg-white flex flex-col animate-in fade-in duration-500 overflow-hidden"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
