      <main className="flex-1 flex flex-col items-center justify-center p-6 relative bg-slate-50/20">
        {/* Dynamic Backgrounds */}
        <div className={`absolute top-0 right-0 w-80 h-80 bg-${currentSection.color}-100/30 rounded-full -mr-40 -mt-40 blur-3xl transition-colors duration-1000`}></div>
        <div className={`absolute bottom-0 left-0 w-80 h-80 bg-${currentSection.color}-100/30 rounded-full -ml-40 -mb-40 blur-3xl transition-colors duration-1000`}></div>

        <div className="w-full max-w-4xl relative z-10">
          {isDetailStep ? (
            /* PAGE 1: INFO / NOTA */
            <div className="space-y-12 animate-in slide-in-from-right-12 duration-500">
               <div className="text-center space-y-6">
                  <div className={`inline-block p-5 rounded-[2rem] bg-${currentSection.color}-50 border-2 border-${currentSection.color}-100 shadow-sm mb-2`}>
                    <span className="text-5xl">📌</span>
                  </div>
                  <h3 className={`text-4xl md:text-6xl font-black text-${currentSection.color}-900 tracking-tight`}>
                    {currentSection.title}
                  </h3>
                  <div className={`h-2.5 w-24 bg-${currentSection.color}-500 rounded-full mx-auto`}></div>
               </div>

               <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-2xl border-4 border-white space-y-10">
                  <div className="space-y-4">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Cara Membaca</p>
                    <p className={`text-2xl md:text-3xl font-bold text-${currentSection.color}-900 leading-relaxed`}>
                      {currentSection.desc}
                    </p>
                  </div>

                  <div className="pt-10 border-t border-slate-50 space-y-8">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Huruf Tajwid</p>
