          )}
        </div>
      </main>

      {/* Nav Footer */}
      <footer className="p-8 flex justify-between items-center bg-white border-t relative z-50">
        <button onClick={prev} className="w-[30%] py-5 bg-gray-50 border border-gray-100 rounded-[2.5rem] font-black text-xs uppercase tracking-widest text-gray-400 active:scale-90 transition-transform">
          {currentStep === 0 ? 'Tutup' : 'Balik'}
