    blue: { bg: 'bg-blue-500', bgLight: 'bg-blue-50', text: 'text-blue-600', textDark: 'text-blue-950', border: 'border-blue-100', shadow: 'shadow-blue-100' },
    rose: { bg: 'bg-rose-500', bgLight: 'bg-rose-50', text: 'text-rose-600', textDark: 'text-rose-950', border: 'border-rose-100', shadow: 'shadow-rose-100' },
