      examples: ['لَعَلَّكُمْ تَتَّقُونَ', 'لَهُمْ fِيهَا', 'أَلَمْ يَعْلَمْ', 'عَلَيْهِمْ غَيْرِ', 'هُمْ fِيهَا', 'أَمْ لَمْ تَنذِرْهُمْ']
    }
  ];

  const totalSteps = sections.length * 2;
  const currentSectionIndex = Math.floor(currentStep / 2);
  const isDetailStep = currentStep % 2 === 0;
  const currentSection = sections[currentSectionIndex] || sections[0];
  const styles = getColorClasses(currentSection.color);

  const playTTS = async (text: string) => {
    if (isLoadingAudio) return;
    setIsLoadingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Bacakan dengan tajwid yang sempurna: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (b64) {
        if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        const ctx = audioCtxRef.current;
        const buf = await decodeAudioData(decode(b64), ctx, 24000, 1);
        const src = ctx.createBufferSource();
        src.buffer = buf;
        src.connect(ctx.destination);
        src.start();
      }
    } catch (e) { console.error(e); } finally { setIsLoadingAudio(false); }
  };

  const next = () => { if (currentStep < totalSteps - 1) setCurrentStep(s => s + 1); else onBack(); };
  const prev = () => { if (currentStep > 0) setCurrentStep(s => s - 1); else onBack(); };

  const onTouchStart = (e: React.TouchEvent) => { touchStartX.current = e.targetTouches[0].clientX; };
  const onTouchMove = (e: React.TouchEvent) => { touchEndX.current = e.targetTouches[0].clientX; };
  const onTouchEnd = () => {
    if (!touchStartX.current || !touchEndX.current) return;
    const distance = touchStartX.current - touchEndX.current;
    if (distance > 50) next(); else if (distance < -50) prev();
  };

  const progress = ((currentStep + 1) / totalSteps) * 100;

  return (
    <div 
      className="fixed inset-0 bg-white flex flex-col animate-in fade-in duration-500 overflow-hidden"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      {/* Header dengan Tajuk Besar */}
      <header className={`px-6 py-5 flex justify-between items-center border-b-2 ${styles.border} bg-white relative z-50`}>
        <button onClick={onBack} className="p-3 text-gray-400 hover:text-emerald-600 transition-colors bg-gray-50 rounded-2xl">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7"/></svg>
        </button>
        <div className="text-center flex-1">
          <h1 className={`${styles.text} font-black text-2xl md:text-3xl tracking-tighter uppercase`}>
            {currentSection.title}
          </h1>
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mt-1">
            {isDetailStep ? 'Panduan Nota' : 'Latihan Contoh'}
          </p>
        </div>
        <div className="text-[11px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-lg">
          {currentStep + 1}/{totalSteps}
        </div>
      </header>

      {/* Progress Bar */}
      <div className="w-full h-2 bg-gray-100 relative z-50">
        <div className={`h-full ${styles.bg} transition-all duration-700 ease-out`} style={{ width: `${progress}%` }}></div>
      </div>

      <main className="flex-1 flex flex-col items-center justify-center p-6 relative bg-slate-50/10">
        {/* Dynamic Backgrounds */}
        <div className={`absolute top-0 right-0 w-[500px] h-[500px] ${styles.bgLight} rounded-full -mr-64 -mt-64 blur-[100px] opacity-40 transition-colors duration-1000`}></div>
        <div className={`absolute bottom-0 left-0 w-[500px] h-[500px] ${styles.bgLight} rounded-full -ml-64 -mb-64 blur-[100px] opacity-40 transition-colors duration-1000`}></div>

        <div className="w-full max-w-4xl relative z-10">
          {isDetailStep ? (
            /* PAGE 1: NOTA */
            <div className="space-y-8 animate-in slide-in-from-right-12 duration-500">
               <div className="bg-white p-10 md:p-14 rounded-[3.5rem] shadow-2xl border-4 border-white space-y-12">
                  <div className="space-y-4">
                    <p className="text-[11px] font-black text-slate-300 uppercase tracking-[0.5em]">Penerangan Hukum</p>
                    <p className={`text-2xl md:text-4xl font-bold ${styles.textDark} leading-tight`}>
                      {currentSection.desc}
                    </p>
                  </div>

                  <div className={`pt-10 border-t-2 ${styles.border} space-y-8`}>
                    <p className="text-[11px] font-black text-slate-300 uppercase tracking-[0.5em]">Huruf Terlibat</p>
                    <div className="flex flex-wrap justify-center gap-4">
                       {currentSection.letters.map((l, i) => (
                         <div key={i} className={`min-w-[6rem] h-24 md:h-32 px-6 ${styles.bgLight} border-4 ${styles.border} rounded-[2.5rem] flex items-center justify-center shadow-md hover:scale-110 transition-transform`}>
                           <span className={`arabic-text text-5xl md:text-7xl ${styles.text}`}>{l}</span>
                         </div>
                       ))}
                    </div>
                  </div>
               </div>
            </div>
          ) : (
            /* PAGE 2: CONTOH */
            <div className="space-y-8 animate-in slide-in-from-right-12 duration-500">
               <div className="grid grid-cols-2 md:grid-cols-3 gap-6" dir="rtl">
                  {currentSection.examples.map((ex, i) => (
                    <button 
                      key={i} 
                      onClick={() => playTTS(ex)}
                      className={`bg-white p-10 md:p-14 rounded-[3.5rem] border-4 border-white shadow-xl hover:border-emerald-400 active:scale-95 transition-all text-center group relative overflow-hidden`}
                    >
                      <div className={`absolute top-4 left-4 w-10 h-10 rounded-2xl ${styles.bgLight} flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity`}>
                        <svg className={`w-5 h-5 ${styles.text}`} fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                      </div>
                      <span className="arabic-text text-4xl md:text-6xl text-slate-900 leading-relaxed block tracking-widest group-hover:scale-110 transition-transform duration-300">
                         {ex}
                      </span>
                    </button>
                  ))}
               </div>
               <div className="bg-white/50 backdrop-blur-md p-6 rounded-3xl border-2 border-white text-center max-w-xl mx-auto">
                  <p className="text-sm font-bold text-slate-500 italic">"Sentuh kotak untuk mendengar sebutan yang betul daripada AI Guru."</p>
               </div>
            </div>
          )}
        </div>
      </main>

      {/* Footer Nav & Branding */}
      <footer className="p-8 pb-10 flex flex-col items-center bg-white border-t-2 border-gray-50 relative z-50 space-y-8">
        <div className="w-full flex justify-between items-center max-w-4xl">
            <button onClick={prev} className="w-[30%] py-5 bg-gray-50 border border-gray-100 rounded-3xl font-black text-xs uppercase tracking-widest text-gray-400 hover:bg-gray-100 active:scale-90 transition-all">
              {currentStep === 0 ? 'Tutup' : 'Balik'}
            </button>

            <div className="flex space-x-4">
              <div className={`w-3 h-3 rounded-full transition-all duration-300 ${isDetailStep ? `${styles.bg} scale-150 shadow-lg` : 'bg-gray-200'}`}></div>
              <div className={`w-3 h-3 rounded-full transition-all duration-300 ${!isDetailStep ? `${styles.bg} scale-150 shadow-lg` : 'bg-gray-200'}`}></div>
            </div>

            <button 
              onClick={next} 
              className={`w-[50%] py-5 ${styles.bg} text-white rounded-3xl font-black text-xs uppercase tracking-widest shadow-2xl ${styles.shadow} hover:brightness-110 active:scale-90 transition-all flex items-center justify-center space-x-3`}
            >
              <span>{currentStep === totalSteps - 1 ? 'Selesai' : 'Seterusnya'}</span>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7"/></svg>
            </button>
        </div>

        {/* Branding Advancekids */}
        <div className="flex flex-col items-center space-y-2 opacity-90 pt-4">
            <Logo size="sm" className="scale-75" />
            <p className="text-[9px] font-black text-gray-400 uppercase tracking-[0.6em] text-center">
                IQRA PINTAR • ADVANCEKIDS MEDIA
            </p>
            <Copyright />
        </div>
      </footer>
    </div>
  );
};

