const getColorClasses = (color: string) => {
  const mapping: Record<string, any> = {
    emerald: { bg: 'bg-emerald-500', bgLight: 'bg-emerald-50', text: 'text-emerald-600', textDark: 'text-emerald-950', border: 'border-emerald-100', shadow: 'shadow-emerald-100' },
    blue: { bg: 'bg-blue-500', bgLight: 'bg-blue-50', text: 'text-blue-600', textDark: 'text-blue-950', border: 'border-blue-100', shadow: 'shadow-blue-100' },
    rose: { bg: 'bg-rose-500', bgLight: 'bg-rose-50', text: 'text-rose-600', textDark: 'text-rose-950', border: 'border-rose-100', shadow: 'shadow-rose-100' },
    amber: { bg: 'bg-amber-500', bgLight: 'bg-amber-50', text: 'text-amber-600', textDark: 'text-amber-950', border: 'border-amber-100', shadow: 'shadow-amber-100' },
    indigo: { bg: 'bg-indigo-500', bgLight: 'bg-indigo-50', text: 'text-indigo-600', textDark: 'text-indigo-950', border: 'border-indigo-100', shadow: 'shadow-indigo-100' },
    slate: { bg: 'bg-slate-500', bgLight: 'bg-slate-50', text: 'text-slate-600', textDark: 'text-slate-950', border: 'border-slate-100', shadow: 'shadow-slate-100' },
    cyan: { bg: 'bg-cyan-500', bgLight: 'bg-cyan-50', text: 'text-cyan-600', textDark: 'text-cyan-950', border: 'border-cyan-100', shadow: 'shadow-cyan-100' },
    violet: { bg: 'bg-violet-500', bgLight: 'bg-violet-50', text: 'text-violet-600', textDark: 'text-violet-950', border: 'border-violet-100', shadow: 'shadow-violet-100' },
  };
  return mapping[color] || mapping.emerald;
};

// Audio Decoding
function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

