export const BISMILLAH = 'بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ';

export const IQRA_1_LETTERS = ['اَ', 'بَ', 'تَ', 'ثَ', 'جَ', 'حَ', 'خَ', 'دَ', 'ذَ', 'رَ', 'زَ', 'سَ', 'شَ', 'صَ', 'ضَ', 'طَ', 'ظَ', 'عَ', 'غَ', 'فَ', 'قَ', 'كَ', 'لَ', 'مَ', 'نَ', 'وَ', 'هَ', 'ءَ', 'يَ'];
export const IQRA_2_DATA = [['اَ', 'اِ', 'اُ'], ['بَ', 'بِ', 'بُ'], ['تَ', 'تِ', 'تُ']];
export const IQRA_3_DATA = [['أً', 'اٍ', 'أٌ'], ['بً', 'بٍ', 'بٌ']];
