import React, { useState, useEffect } from 'react';
import SplashScreen from './components/SplashScreen';
import LoginPage from './components/LoginPage';
import ProfileSetup from './components/ProfileSetup';
import ProfileView from './components/ProfileView';
import LevelDetail from './components/LevelDetail';
import SubMenu from './components/SubMenu';
import PracticeSession from './components/PracticeSession';
import Juz30Menu from './components/Juz30Menu';
import Quiz from './components/Quiz';
import Logo from './components/Logo';
import Copyright from './components/Copyright';
import { User, AppState, IqraLevel } from './types';
import { IQRA_LEVELS } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.SPLASH);
  const [user, setUser] = useState<User | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<IqraLevel | null>(null);
  const [unlockedLevels, setUnlockedLevels] = useState<number[]>([1]); 

  useEffect(() => {
    const savedProgress = localStorage.getItem('advancekids_iqra_progress');
    const savedUser = localStorage.getItem('advancekids_user');
    if (savedProgress) setUnlockedLevels(JSON.parse(savedProgress));
    if (savedUser) {
      const u = JSON.parse(savedUser);
      setUser(u);
      if (u.isAdmin) setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    }
  }, []);

  const handleSubMenuOption = (option: 'PRACTICE' | 'LEVEL' | 'QUIZ') => {
    if (option === 'PRACTICE') {
      if (selectedLevel?.id === 9) setAppState(AppState.JUZ30);
      else setAppState(AppState.PRACTICE);
    } else if (option === 'LEVEL') {
      setAppState(AppState.LEVEL);
    } else {
      setAppState(AppState.QUIZ);
    }
  };

  const renderContent = () => {
    switch (appState) {
      case AppState.SPLASH: return <SplashScreen onFinish={() => setAppState(AppState.LOGIN)} />;
      case AppState.LOGIN: return <LoginPage onLogin={(admin) => {
        if (admin) {
          const adminUser = { name: 'Admin', photoURL: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Admin', isAdmin: true } as User;
          setUser(adminUser);
          setUnlockedLevels([1, 2, 3, 4, 5, 6, 7, 8, 9]);
          setAppState(AppState.MENU);
        } else setAppState(AppState.PROFILE_SETUP);
      }} />;
      case AppState.PROFILE_SETUP: return <ProfileSetup onComplete={(u) => { setUser(u); setAppState(AppState.MENU); }} />;
      case AppState.MENU: return (
        <div className="h-screen flex flex-col bg-slate-50 overflow-hidden">
          <header className="px-6 py-4 flex justify-between items-center bg-white border-b flex-shrink-0">
            <Logo size="sm" />
            <button onClick={() => setAppState(AppState.PROFILE_VIEW)} className="flex items-center space-x-3 bg-slate-50 p-1 pr-4 rounded-full border border-slate-100 hover:scale-105 transition-all">
              <img src={user?.photoURL} className="w-8 h-8 rounded-full border border-emerald-400 object-cover" />
              <div className="text-left leading-none">
                <p className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Pelajar</p>
                <p className="text-xs font-bold text-gray-800">{user?.name.split(' ')[0]}</p>
              </div>
            </button>
          </header>
          <main className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
            <div className="text-center space-y-1">
              <h2 className="text-2xl md:text-3xl font-black text-[#1B1C57]">Sedia untuk Belajar?</h2>
              <p className="text-gray-400 text-sm font-medium">Pilih tahap IQRA anda di bawah.</p>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 pb-10">
              {IQRA_LEVELS.map((level) => {
                const unlocked = unlockedLevels.includes(level.id);
                return (
                  <button key={level.id} disabled={!unlocked} onClick={() => { setSelectedLevel(level); setAppState(AppState.SUBMENU); }}
                    className={`aspect-square p-4 rounded-3xl text-left transition-all border-2 flex flex-col justify-center items-center text-center ${unlocked ? 'bg-white border-white shadow-md hover:scale-105 active:scale-95' : 'bg-slate-100 border-slate-200 opacity-60'}`}>
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-2xl mb-2 ${unlocked ? level.color : 'bg-slate-300'} text-white shadow-sm`}>{level.icon}</div>
                    <h3 className={`text-sm font-black ${unlocked ? 'text-[#1B1C57]' : 'text-slate-400'}`}>{level.title}</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase truncate w-full">{level.subtitle}</p>
                  </button>
                );
              })}
            </div>
          </main>
          <footer className="bg-white border-t py-2 flex-shrink-0"><Copyright /></footer>
        </div>
      );
      case AppState.SUBMENU: return selectedLevel && <SubMenu level={selectedLevel} onBack={() => setAppState(AppState.MENU)} onSelectOption={handleSubMenuOption} />;
      case AppState.LEVEL: return selectedLevel && <LevelDetail level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} showStartButton onStartPractice={() => handleSubMenuOption('PRACTICE')} />;
      case AppState.PRACTICE: return selectedLevel && <PracticeSession level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.QUIZ)} />;
      case AppState.JUZ30: return <Juz30Menu onBack={() => setAppState(AppState.SUBMENU)} />;
      case AppState.QUIZ: return selectedLevel && <Quiz level={selectedLevel} onBack={() => setAppState(AppState.SUBMENU)} onFinish={() => setAppState(AppState.MENU)} />;
      case AppState.PROFILE_VIEW: return user && <ProfileView user={user} unlockedLevels={unlockedLevels} levels={IQRA_LEVELS} onBack={() => setAppState(AppState.MENU)} />;
      default: return null;
    }
  };

  return <div className="h-screen bg-slate-50 font-sans select-none">{renderContent()}</div>;
};

export default App;

