import React, { useState, useEffect, useMemo, useRef } from 'react';
// Corrected import: JUZ_30_DATA does not exist in constants.tsx, use JUZ_AMMA_LIST instead
import { IQRA_1_LETTERS, IQRA_2_DATA, IQRA_3_DATA, IQRA_4_DATA, IQRA_5_DATA, IQRA_6_DATA, IQRA_7_DATA, IQRA_8_DATA, JUZ_AMMA_LIST, BISMILLAH } from '../constants';
import { IqraLevel, SurahData } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";
